# Stories for albums 901–950 (long format agreed with the owner: three paragraphs + a listening tip,
# ~220–230 words per story (min ~210), three picks with ~12-word notes). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_901_950.py; later edits: python3 tools/apply_stories.py stories_901_950
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(901, [
'''סיגור רוס היא להקה מרייקיאוויק שבאיסלנד, אותה ארץ קטנה וקרה שנתנה לעולם גם את ביורק (אלבום 749). הזמר והגיטריסט יונסי מנגן על הגיטרה שלו בקשת של צ׳לו, ויוצר צליל ארוך, מהדהד ומרחף, ושר בקול גבוה ושביר במיוחד, כמעט כמו של מלאך. Ágætis byrjun, ששמו פירושו "התחלה טובה", יצא באיסלנד באמצע 1999, ושנה אחר כך בשאר העולם. מבקרים התלהבו, רדיוהד הזמינו את הלהקה לחמם את ההופעות שלהם, ופתאום כולם רצו לשמוע את הצלילים המוזרים והיפים מהצפון.''',
'''המוזיקה איטית, רחבה וחגיגית, כמו נוף של קרחונים, הרים ושמיים ענקיים: גיטרה בקשת, עוגב, כלי מיתר, כלי נשיפה, פסנתר ותופים שנכנסים לאט, והכל נבנה בהדרגה לשיאים אדירים ומרגשים. יונסי שר באיסלנדית, ולפעמים בשפה מומצאת בלי מילים של ממש, שהלהקה קוראת לה "תקוותית", כך שהקול הופך לעוד כלי נגינה. Svefn-g-englar, אחד הקטעים המפורסמים, נפתח בצליל דמוי סונאר תת־ימי, ונבנה לאט לרגע מרהיב. Starálfur, עם כלי מיתר, הוא שיר עדין ויפה כמו אגדה. Viðrar vel til loftárása, ששמו פירושו "מזג אוויר טוב להפצצה אווירית", מתחיל בשקט מוחלט ומגיע לשיא עצום של כלי מיתר ותופים.''',
'''Ágætis byrjun הפך את סיגור רוס לאחת הלהקות המוערכות בעולם, והקטעים שלו הופיעו מאז באינספור סרטים, סדרות ופרסומות. הוא השפיע על להקות פוסט רוק רבות, והוכיח שאפשר לרגש קהל עצום בשפה שאיש לא מבין.''',
'''זה אלבום שצריך לשמוע באוזניות, בחושך או בנסיעה ארוכה בטבע. אל תנסו להבין את המילים, רק תנו לקול לסחוף אתכם. ואם אהבתם את Millions Now Living Will Never Die של טורטויז (אלבום 812), תמצאו כאן צד רגשי יותר של אותו רעיון.''',
], [
('Svefn-g-englar', 'צליל סונאר תת־ימי שנבנה לאט לרגע מרהיב, עם קול מלאכי.'),
('Starálfur', 'שיר עדין ויפה עם כלי מיתר, כמו אגדה מהצפון.'),
('Viðrar vel til loftárása', 'מתחיל בשקט מוחלט ומגיע לשיא עצום של כלי מיתר ותופים.'),
])

add(902, [
'''דאבז הם שלושה מוזיקאים ממנצ׳סטר: ג׳ימי גודווין והתאומים ג׳ז ואנדי וויליאמס. בתחילת שנות התשעים הם היו להקת דאנס בשם סאב סאב, עם להיט אחד מצליח, אבל ב־1996 פרצה שריפה באולפן שלהם, והשמידה כמעט את כל הציוד וההקלטות. הם החליטו להתחיל מחדש, לגמרי אחרת: עם גיטרות, תופים ושירה, כלהקת רוק. Lost Souls, אלבום הבכורה של דאבז, יצא באביב 2000, היה מועמד לפרס מרקורי, וזכה לשבחים רבים מצד מבקרים ומוזיקאים.''',
'''הצליל רחב, מלנכולי ומרחף, כמו נוף עירוני בשעת דמדומים: גיטרות מהדהדות, תופים איטיים וכבדים, קלידים, צלילים אלקטרוניים עדינים שנשארו מתקופת הדאנס, ושירה עייפה ויפה של גודווין וג׳ז וויליאמס. השירים עוסקים באובדן, בגעגועים ובתקווה, ונשמעים כמו פסקול של עיר צפונית אפורה בחורף. The Cedar Room הוא שיר ארוך ודרמטי, שנבנה מגיטרות שקטות לשיא אדיר וסוחף. Catch the Sun הוא שיר קצבי ושמשי יותר, עם פזמון שמזמין לשיר, והגיע למצעד הבריטי. Here It Comes הוא שיר עדין ומהפנט, עם קול רך ומלודיה נוגה.''',
'''Lost Souls נחשב לאחד האלבומים היפים של תחילת שנות האלפיים בבריטניה, והוא השפיע על להקות רבות שחיפשו צליל רחב ורגשי. האלבום הבא של דאבז הגיע למקום הראשון במצעד הבריטי, והלהקה הפכה לאחת האהובות של מנצ׳סטר, העיר של הסטון רוזס (אלבום 646) ושל ג׳וי דיוויז׳ן.''',
'''שמעו את The Cedar Room באוזניות, ותנו לו להיבנות לאט עד השיא. וזה אלבום טוב במיוחד לערב גשום, כשמסתכלים מהחלון.''',
], [
('The Cedar Room', 'שיר ארוך ודרמטי, מגיטרות שקטות לשיא אדיר וסוחף.'),
('Catch the Sun', 'שיר קצבי ושמשי, עם פזמון שמזמין לשיר.'),
('Here It Comes', 'שיר עדין ומהפנט, עם קול רך ומלודיה נוגה.'),
])

add(903, [
'''אחרי ההצלחה העולמית של Moon Safari (אלבום 874), צמד הצרפתים אייר קיבל הצעה מעניינת: סופיה קופולה, בתו של הבמאי פרנסיס פורד קופולה, ביקשה מהם לכתוב את הפסקול לסרט הראשון שביימה, The Virgin Suicides, על פי ספר של ג׳פרי יוג׳נידס. הסרט מספר על חמש אחיות מתבגרות בפרבר אמריקאי בשנות השבעים, ועל הנערים מהשכונה שמנסים להבין אותן ולא מצליחים. הפסקול יצא כאלבום בתחילת 2000, ורבים רואים בו את אחת היצירות היפות של הצמד.''',
'''במקום הפופ השמשי והקליל של Moon Safari, כאן המוזיקה אפלה, חלומית ומלנכולית, כמו זיכרון מטושטש של קיץ עצוב: סינתיסייזרים ישנים, עוגב, פסנתר, גיטרות רכות, תופים איטיים ומקהלות מרחפות, בהשראת הרוק המתקדם והפסקולים של שנות השבעים. רוב הקטעים כליים, וכל אחד מהם מתאר תחושה או רגע מהסרט. Playground Love, השיר היחיד עם שירה של ממש, מושר בידי זמר צעיר מלהקה צרפתית אחרת, תחת שם בדוי, והוא שיר אהבה עדין, מתוק ועצוב, עם סקסופון ופסנתר. Highschool Lover הוא קטע פסנתר נוגה ויפה, שחוזר על אותה מנגינה. Dead Bodies הוא קטע אפל ומאיים, עם עוגב ותופים.''',
'''האלבום הזה הוכיח שאייר יודעים לעשות הרבה יותר מפופ נעים, והפך לאחד הפסקולים האהובים של התקופה. השיתוף בין אייר לבין סופיה קופולה המשיך גם בסרטים הבאים שלה.''',
'''אפשר לשמוע את האלבום לבד, אבל עוד יותר יפה לראות קודם את הסרט ואז לשמוע אותו. והשוו את Playground Love ל־Sexy Boy מ־Moon Safari (אלבום 874).''',
], [
('Playground Love', 'שיר אהבה עדין ועצוב, עם סקסופון, פסנתר וקול רך.'),
('Highschool Lover', 'קטע פסנתר נוגה ויפה, שחוזר על אותה מנגינה.'),
('Dead Bodies', 'קטע אפל ומאיים, עם עוגב ותופים כבדים.'),
])

add(904, [
'''ראיין אדמס גדל בעיירה בצפון קרוליינה, ובסוף שנות התשעים הוביל את וויסקיטאון, להקת אלט קאנטרי מוערכת, שחיברה קאנטרי עם אנרגיה של פאנק. אחרי שהלהקה התפרקה, ואחרי פרידה כואבת מבת זוגו, הוא נסע לנאשוויל והקליט בתוך שבועיים בערך את אלבום הסולו הראשון שלו, Heartbreaker, שיצא בסתיו 2000. האלבום זכה לשבחים גדולים, והפך את אדמס לאחד מכותבי השירים המדוברים של אמריקה. בשנים מאוחרות יותר עלו נגדו טענות קשות על התנהגותו כלפי נשים.''',
'''המוזיקה פשוטה וכנה: גיטרה אקוסטית, מפוחית, פסנתר, מעט תופים וכינור, ובעיקר הקול של אדמס, מחוספס, פגיע ומלא רגש. השירים עוסקים באהבה שנגמרה, בגעגוע, בשתייה ובבדידות, בהשראת ניל יאנג, גראם פרסונס (אלבום 325) ובוב דילן. האלבום נפתח בשיחה מצחיקה באולפן, שבה אדמס מתווכח עם חבר על שיר של מוריסי, ואז מתחיל לנגן. Oh My Sweet Carolina, עם אמילו האריס בקולות, הוא שיר געגועים יפה ושקט לבית ולמולדת. Come Pick Me Up הוא שיר פרידה מר ומצחיק, עם בנג׳ו ומפוחית, על מי שעדיין מתגעגע למי שפגעה בו. To Be Young (Is to Be Sad, Is to Be High) הוא שיר מהיר ופרוע, עם גיטרה מתגלגלת.''',
'''Heartbreaker נחשב לאחד מאלבומי האמריקנה החשובים של תחילת שנות האלפיים, ולאחד הטובים של אדמס, שהמשיך להוציא אלבומים רבים בקצב מהיר מאוד.''',
'''שמעו את Oh My Sweet Carolina, ושימו לב לקולה של אמילו האריס, שנכנס בעדינות. והשוו את האלבום ל־Car Wheels on a Gravel Road של לוסינדה וויליאמס (אלבום 866).''',
], [
('Oh My Sweet Carolina', 'שיר געגועים יפה ושקט, עם קולה של אמילו האריס.'),
('Come Pick Me Up', 'שיר פרידה מר ומצחיק, עם בנג׳ו ומפוחית.'),
('To Be Young (Is to Be Sad, Is to Be High)', 'שיר מהיר ופרוע, עם גיטרה מתגלגלת וקול מחוספס.'),
])

add(905, [
'''בבל ז׳ילברטו נולדה בניו יורק למשפחה שהיא כמעט מלכות של המוזיקה הברזילאית: אביה הוא ז׳ואאו ז׳ילברטו, ממציאי הבוסה נובה (אלבום 41), אמה היא הזמרת מיושה, ודודה הוא כותב השירים הגדול שיקו בוארקי. היא שרה כבר כילדה, וגדלה בין ריו דה ז׳ניירו לניו יורק. Tanto Tempo, אלבום הבכורה שלה, יצא ב־2000, ואת רובו הפיק סובה (אלבום 880), שמת בשריפה באולפן שלו לפני שהאלבום יצא. הוא הפך לאחד האלבומים הברזילאים הנמכרים באמריקה ובאירופה.''',
'''המוזיקה מחברת את הבוסה נובה הקלאסית, הרכה והלוחשת של אביה, עם צלילים אלקטרוניים עדינים, קצבים רגועים, בס עמוק ומיתרים. בבל שרה בפורטוגזית ובאנגלית, בקול נמוך, רך ומפתה, כמו לחישה באוזן. חלק מהשירים כתבה בעצמה, וחלקם שירים ברזילאיים ידועים בעיבודים חדשים. Samba da Benção, שפותח את האלבום, הוא גרסה לשיר קלאסי ידוע, מעל קצב אלקטרוני רך. Tanto Tempo, השיר שנתן לאלבום את שמו, הוא שיר לילי ויפה, עם קצב מהפנט וקול לוחש. So Nice (Summer Samba) היא גרסה מתוקה לשיר קיץ ברזילאי מפורסם משנות השישים.''',
'''Tanto Tempo הפך לאחד האלבומים המזוהים עם תחילת שנות האלפיים, ונשמע בבתי קפה, במסעדות ובמועדונים רגועים בכל העולם. הוא הציג את הבוסה נובה לדור חדש, ושמר על המורשת של סובה, שהקדיש את שנותיו האחרונות לחיבור בין ברזיל לבין המוזיקה האלקטרונית.''',
'''השוו את Tanto Tempo ל־Getz/Gilberto (אלבום 41), שבו שר אביה של בבל, ושמעו את הבוסה נובה בשני דורות. וזה אלבום מושלם לערב קיץ רגוע.''',
], [
('Samba da Benção', 'גרסה לשיר ברזילאי קלאסי, מעל קצב אלקטרוני רך.'),
('Tanto Tempo', 'שיר לילי ויפה, עם קצב מהפנט וקול לוחש.'),
('So Nice (Summer Samba)', 'גרסה מתוקה לשיר קיץ ברזילאי מפורסם מהשישים.'),
])

add(906, [
'''MJ קול, מאט קולמן, גדל בלונדון ולמד מוזיקה קלאסית בצעירותו, לפני שהתאהב במוזיקת המועדונים של סוף שנות התשעים. הוא עבד כמהנדס קול בחברת תקליטים קטנה, ושם התחיל להפיק בעצמו קטעים של "יו־קיי גראז׳", סגנון לונדוני חדש שחיבר האוס, רית׳ם אנד בלוז ודראם אנד בייס, עם קצב קופצני ושבור שנקרא "טו סטפ". הסינגל Sincere הפך ללהיט מחתרתי, ואלבום הבכורה שלו, שנקרא באותו שם, יצא ב־2000 והיה מועמד לפרס מרקורי.''',
'''המוזיקה אלגנטית, חלקה וקופצנית, כמו לונדון בלילה: קצבים מקפיצים ושבורים, בס עמוק ומתגלגל, אקורדים של ג׳אז ופסנתר חשמלי, כלי מיתר, וקולות נשיים רכים של זמרות סול צעירות. ההשכלה הקלאסית של קול נשמעת בעיבודים המדויקים והעשירים, שמבדילים אותו ממפיקים אחרים של אותה סצנה. Sincere, השיר שנתן לאלבום את שמו, הוא קטע מקפיץ עם קולות חמים, ששמו נשמע כמו הצהרה. Crazy Love, עם הזמרת אליזבת טרוי, הוא שיר אהבה שמח וקליל, שהגיע למצעד הבריטי. Hold On to Me, גם הוא עם טרוי, הוא שיר רך ומלנכולי, עם קצב איטי יותר ופסנתר.''',
'''Sincere נחשב לאחד האלבומים החשובים של היו־קיי גראז׳, הסגנון שהביא לעולם כוכבים כמו קרייג דייוויד, ושהיה השורש לסגנונות בריטיים רבים שבאו אחריו, כמו גרייים ודאבסטפ. האלבום עדיין נשמע רענן, והשפיע גם על מפיקים צעירים בשנים האחרונות.''',
'''שמעו את Crazy Love, ושימו לב לקצב הקופצני והשבור, שהוא סימן ההיכר של הטו סטפ. והשוו ל־New Forms של רוני סייז (אלבום 855), עוד צד של המוזיקה האלקטרונית הבריטית באותן שנים.''',
], [
('Sincere', 'קטע מקפיץ ואלגנטי, עם קולות חמים ובס מתגלגל.'),
('Crazy Love', 'שיר אהבה שמח וקליל, עם קולה של אליזבת טרוי.'),
('Hold On to Me', 'שיר רך ומלנכולי, עם קצב איטי ופסנתר.'),
])

add(907, [
'''אמילו האריס הייתה כבר שלושים שנה אחת הזמרות האהובות של הקאנטרי והפולק, מאז ימיה עם גראם פרסונס (אלבום 325) ואלבומים כמו Pieces of the Sky (אלבום 335). אבל במשך כל השנים האלה היא שרה בעיקר שירים של אחרים, והייתה ידועה כמפרשת נפלאה ולא ככותבת. Red Dirt Girl, שיצא ב־2000, היה שונה: את כמעט כל השירים בו היא כתבה בעצמה, לבד או עם אחרים. הוא זכה בגראמי, ורבים רואים בו את אחד האלבומים האישיים והיפים שלה.''',
'''הצליל עמוק, אפל ומהדהד, בהשפעת המפיק דניאל לנואה, שעבד איתה על האלבום הקודם: גיטרות מעובדות, תופים עמומים, בס עמוק ואווירה ערפילית, ומעל הכל קולה הצלול והעצוב של האריס, שנשמע כאן בוגר ומלא חוכמה. השירים עוסקים בזיכרונות, במוות, באמונה ובאהבה. Red Dirt Girl, השיר שנתן לאלבום את שמו, מספר על חברת ילדות מאלבמה, שחלמה לברוח מהעיירה הקטנה ונשארה בה עד מותה בגיל צעיר. Bang the Drum Slowly הוא שיר מרגש לזכר אביה, קצין בחיל הנחתים האמריקאי שנפל בשבי בזמן מלחמת קוריאה. Michelangelo הוא שיר חלומי ומסתורי, עם מילים יפות ומלודיה נוגה.''',
'''Red Dirt Girl הראה שאמילו האריס, אחרי עשרות שנים על הבמה, היא גם כותבת שירים מצוינת. בין האורחים באלבום יש מוזיקאים כמו ברוס ספרינגסטין, והוא נשאר אחד האלבומים האהובים במיוחד על מעריציה.''',
'''שמעו את Red Dirt Girl, והקשיבו לסיפור. והשוו את הקול של האריס כאן ל־Pieces of the Sky (אלבום 335), כדי לשמוע איך הוא העמיק בעשרים וחמש שנים.''',
], [
('Red Dirt Girl', 'סיפור על חברת ילדות מאלבמה, שחלמה לברוח ולא הצליחה.'),
('Bang the Drum Slowly', 'שיר מרגש לזכר אביה, קצין שנפל בשבי במלחמת קוריאה.'),
('Michelangelo', 'שיר חלומי ומסתורי, עם מילים יפות ומלודיה נוגה.'),
])

add(908, [
'''לימפ ביזקיט הגיעו מג׳קסונוויל שבפלורידה, בהנהגת הזמר פרד דרסט, שהיה כבר ידוע כאחד הדמויות הבולטות והשנויות במחלוקת של הנו מטאל, עם כובע בייסבול הפוך ויהירות מתגרה. הגיטריסט ווס בורלנד, עם איפור ותלבושות מטורפות, והתקליטן DJ לית׳ל, שניגן בעבר בלהקת היפ הופ, נתנו ללהקה צליל ודימוי ייחודיים. Chocolate Starfish and the Hot Dog Flavored Water, אלבום עם שם מוזר ומצחיק, יצא בסתיו 2000, ונמכר ביותר ממיליון עותקים באמריקה כבר בשבוע הראשון, שיא לאלבום רוק באותה תקופה.''',
'''המוזיקה מחברת רוק כבד ומטאל עם היפ הופ: גיטרות נמוכות וכבדות, תופים מקפיצים, שריטות של תקליטן, וראפ זועם ומתגרה של דרסט, שעובר לפעמים לשירה מלודית. Rollin' (Air Raid Vehicle) הוא השיר המפורסם, שיר מקפיץ ופשוט שמזמין קהל שלם לקפוץ ולצעוק יחד, והפך לאחד המנוני המסיבות של התקופה. My Way הוא שיר כבד ומלודי יותר, על התעקשות ללכת בדרך שלך. Take a Look Around, שנכתב לסרט "משימה בלתי אפשרית 2", מבוסס על נעימת הנושא המפורסמת של הסדרה, והפך ללהיט. המילים בוטות מאוד, ומלאות כעס ויהירות.''',
'''האלבום היה שיא ההצלחה של לימפ ביזקיט, ושל גל הנו מטאל כולו. מבקרים רבים לעגו לו, אבל הוא נשאר מסמך מדויק של תחילת שנות האלפיים, ושל דור של בני נוער כועסים שמצא בו קול.''',
'''שמעו את Rollin' (Air Raid Vehicle), ונסו לא לקפוץ. והשוו את האלבום ל־Follow the Leader של קורן (אלבום 876), הלהקה שפתחה את הדלת ללימפ ביזקיט.''',
], [
("Rollin' (Air Raid Vehicle)", 'שיר מקפיץ ופשוט, שמזמין קהל שלם לקפוץ ולצעוק יחד.'),
('My Way', 'שיר כבד ומלודי, על התעקשות ללכת בדרך שלך.'),
('Take a Look Around', 'שיר מבוסס על נעימת הנושא של "משימה בלתי אפשרית".'),
])

add(909, [
'''אחרי ההצלחה העצומה של OK Computer (אלבום 837), רדיוהד היו מותשים. הזמר תום יורק סבל ממשבר כתיבה, נמאס לו מגיטרות ומשירי רוק, והתחיל להקשיב בעיקר למוזיקה אלקטרונית, כמו של אפקס טווין (אלבום 708), ולג׳אז. Kid A, שיצא בסתיו 2000, היה התוצאה: אלבום ניסיוני, קר ומסתורי, כמעט בלי גיטרות, שהפתיע והבהיל חלק מהמעריצים. הלהקה לא הוציאה ממנו אף סינגל ולא צילמה קליפים, ובכל זאת הוא נכנס ישר למקום הראשון במצעד האמריקאי.''',
'''המוזיקה בנויה מסינתיסייזרים, מכונות תופים, פסנתר חשמלי, כלי מיתר, כלי נשיפה של ג׳אז, וגלי מרטנו, כלי אלקטרוני ישן וצרפתי שג׳וני גרינווד מנגן עליו. הקול של יורק מעובד, מקוטע וקשה להבנה, והמילים הן משפטים מוזרים ומפוזרים, כמו חלום. Everything in Its Right Place, שיר הפתיחה, מתחיל בפסנתר חשמלי חם וקול שחוזר על עצמו, ויוצר תחושה מהפנטת. How to Disappear Completely הוא שיר יפה ועצוב, עם כלי מיתר מרחפים, על תחושה של מי שרוצה להיעלם. Idioteque הוא שיר אלקטרוני מהיר ומפחיד, על פחד מאסון, עם תופים חדים וקול לחוץ.''',
'''Kid A נבחר שוב ושוב לאחד האלבומים החשובים של המאה העשרים ואחת, והראה שלהקה גדולה יכולה לוותר על הנוסחה שלה ולהמציא את עצמה מחדש. הוא זכה בגראמי לאלבום האלטרנטיבי הטוב ביותר.''',
'''שמעו את Kid A ברצף, בחושך ובאוזניות, ואל תחפשו בו להיטים. והשוו את Everything in Its Right Place ל־Airbag מ־OK Computer (אלבום 837), כדי לשמוע את הקפיצה.''',
], [
('Everything in Its Right Place', 'פסנתר חשמלי חם וקול חוזר, פתיחה מהפנטת ומסתורית.'),
('How to Disappear Completely', 'שיר יפה ועצוב עם כלי מיתר, על רצון להיעלם.'),
('Idioteque', 'שיר אלקטרוני מהיר ומפחיד, עם תופים חדים וקול לחוץ.'),
])

add(910, [
'''בשנות התשעים U2 עשו ניסויים רבים: אחרי Achtung Baby (אלבום 701) הם הוציאו אלבומים אלקטרוניים, אירוניים ומוזרים, עם הופעות ענק מלאות מסכים ושלטים, ובסוף העשור רבים הרגישו שהלהקה איבדה את הדרך. All That You Can't Leave Behind, שיצא בסתיו 2000, היה החזרה הגדולה שלהם לשורשים: שירים פשוטים, חמים ומלאי רגש, עם גיטרה, בס, תופים וקולו של בונו. את האלבום הפיקו שוב בריאן אינו ודניאל לנואה, שעבדו איתם על The Joshua Tree (אלבום 608).''',
'''הצליל נקי, רחב ומלא תקווה, עם הגיטרה המצלצלת והמהדהדת של דה אדג׳, ומלודיות גדולות שנועדו לשירה יחד באצטדיונים. השירים עוסקים באהבה, באובדן, באמונה ובחשיבות של לא לוותר. Beautiful Day, הלהיט הגדול, הוא שיר אופטימי וסוחף על היכולת לראות יופי גם בתקופה קשה, והוא זכה בשלושה פרסי גראמי. Stuck in a Moment You Can't Get Out Of הוא שיר גוספל עדין, שנכתב לזכר הזמר מייקל האצ׳נס, חברו של בונו. Walk On הוא המנון מרגש, שהוקדש לפוליטיקאית הבורמזית אונג סן סו צ׳י, שישבה במעצר בית.''',
'''אחרי פיגועי 11 בספטמבר 2001, כמה מהשירים באלבום הפכו להמנונים של נחמה, ו־U2 הופיעו במחצית של הסופרבול, האירוע הנצפה ביותר באמריקה, כשעל מסך ענק מאחוריהם הוקרנו שמות הנרצחים. האלבום החזיר אותם למעמד של אחת הלהקות הגדולות בעולם.''',
'''השוו את Beautiful Day ל־Where the Streets Have No Name מ־The Joshua Tree (אלבום 608), ושמעו את אותה גיטרה מצלצלת, שלוש עשרה שנים אחר כך.''',
], [
('Beautiful Day', 'שיר אופטימי וסוחף על יופי בתקופה קשה, זכה בשלושה גראמי.'),
("Stuck in a Moment You Can't Get Out Of", 'שיר גוספל עדין, לזכר הזמר מייקל האצ׳נס.'),
('Walk On', 'המנון מרגש, שהוקדש לאונג סן סו צ׳י.'),
])

add(911, [
'''לינקין פארק נולדה בפרברים של לוס אנג׳לס, סביב מייק שינודה, ראפר, מפיק ואמן גרפי, וחברי תיכון שלו. ב־1999 הצטרף אליהם צ׳סטר בנינגטון מאריזונה, זמר בעל קול מדהים, שיכול היה לעבור בשנייה משירה מלודית ורכה לצעקה כואבת ועוצמתית. Hybrid Theory, אלבום הבכורה שלהם, יצא בסתיו 2000, והפך לאחד מאלבומי הבכורה הנמכרים ביותר של המאה העשרים ואחת, עם עשרות מיליוני עותקים בכל העולם. שמו לקוח מהשם הראשון של הלהקה.''',
'''הצליל מחבר רוק כבד ומטאל עם היפ הופ ומוזיקה אלקטרונית: גיטרות כבדות ונמוכות, תופים חזקים, שריטות של תקליטן, דגימות וצלילים אלקטרוניים, והשילוב בין הראפ של שינודה לבין השירה והצעקות של בנינגטון. השירים קצרים, מדויקים ומלאי פזמונים, והמילים עוסקות בכאב, בכעס, בבדידות ובתחושה של מי שלא מצליח להשתחרר מעצמו. In the End, הלהיט הגדול, נפתח במלודיית פסנתר פשוטה ובלתי נשכחת, ומחבר ראפ רגוע עם פזמון כואב. Crawling, שזכה בגראמי, הוא שיר על מאבק פנימי, עם צעקה אדירה בפזמון. One Step Closer הוא שיר זועם ומהיר, על הרגע שבו נגמרת הסבלנות.''',
'''Hybrid Theory הפך את לינקין פארק לאחת הלהקות הגדולות בעולם, ודיבר אל מיליוני בני נוער שמצאו בשירים שלה מילים לכאב שלהם. צ׳סטר בנינגטון מת ב־2017, והשירים מהאלבום הזה קיבלו אז משמעות חדשה ועצובה עוד יותר.''',
'''שמעו את In the End, ושימו לב איך הראפ השקט והשירה הכואבת משלימים זה את זה. והשוו ל־Follow the Leader של קורן (אלבום 876), שהשפיע עליהם מאוד.''',
], [
('In the End', 'מלודיית פסנתר בלתי נשכחת, ראפ רגוע ופזמון כואב.'),
('Crawling', 'שיר על מאבק פנימי, עם צעקה אדירה בפזמון.'),
('One Step Closer', 'שיר זועם ומהיר, על הרגע שבו נגמרת הסבלנות.'),
])

add(912, [
'''אחרי Either/Or (אלבום 856) והמועמדות לאוסקר, אליוט סמית׳ חתם בחברת תקליטים גדולה, ופתאום היו לו תקציב, אולפנים ונגנים. Figure 8, שיצא באביב 2000, הוקלט בחלקו בלוס אנג׳לס ובחלקו באולפני אבי רואד המפורסמים בלונדון, שבהם הקליטו הביטלס, שסמית׳ העריץ. הצליל שלו התרחב מאוד: במקום הגיטרה האקוסטית הלוחשת, יש כאן להקה מלאה, פסנתר, כלי מיתר וכלי נשיפה, וכתיבה שאפתנית שמזכירה את הפופ המתוחכם של הביטלס בסוף שנות השישים.''',
'''למרות הצליל העשיר, הלב נשאר אותו לב: קולו הרך, הכפול והשביר של סמית׳, ומלודיות יפות שמסתירות מילים עצובות על בדידות, על התמכרות ועל קשיים בתקשורת עם אנשים. האלבום ארוך ומגוון, עם שירים קצרים וקטעים כליים קטנים בין השירים. Son of Sam, שפותח את האלבום, הוא שיר רוק קצבי עם פסנתר וגיטרות, ומילים מסתוריות ואפלות. Happiness הוא שיר מתוק ומלא תקווה, עם פזמון שחוזר על הרצון להיות מאושר. Everything Means Nothing to Me הוא שיר יפה ומשונה, עם פסנתר ושירה מרחפת, שנשמע כמו חלום.''',
'''Figure 8 היה אלבום הסולו האחרון שסמית׳ השלים בחייו. על העטיפה הוא מצולם מול ציור קיר צבעוני ברחוב בלוס אנג׳לס, ואחרי מותו ב־2003 הפך הקיר הזה לאתר זיכרון, שמעריצים מגיעים אליו עם פרחים ומכתבים. מבקרים רבים רואים בו את האלבום השאפתני ביותר שלו, גם אם חלק מהמעריצים התגעגעו לשקט של האלבומים הקודמים.''',
'''השוו בין Figure 8 לבין Either/Or (אלבום 856): אותו כותב, אבל עם תזמורת במקום חדר שקט. והתחילו ב־Happiness.''',
], [
('Son of Sam', 'שיר רוק קצבי עם פסנתר וגיטרות, ומילים אפלות ומסתוריות.'),
('Happiness/The Gondola Man', 'שיר מתוק ומלא תקווה, עם פזמון על הרצון להיות מאושר.'),
('Everything Means Nothing to Me', 'שיר יפה ומשונה עם פסנתר, שנשמע כמו חלום.'),
])

add(913, [
'''באדלי דרואן בוי, "ילד שצויר רע", הוא דיימון גוף מבולטון, עיירה ליד מנצ׳סטר, שתמיד הופיע עם כובע צמר מרופט על הראש, וזקן פרוע. הוא היה מוזיקאי שעשה הכל לבד: כתב, ניגן על כלים רבים, הקליט בבית, ואפילו ניהל חברת תקליטים קטנה עם חברים. The Hour of Bewilderbeast, אלבום הבכורה שלו, יצא באמצע 2000, וזכה בפרס מרקורי באותה שנה, כשהוא עוקף בין היתר את Parachutes של קולדפליי (אלבום 916).''',
'''האלבום ארוך, ביתי ומבולגן באופן מקסים, עם שמונה עשר שירים וקטעים, ונשמע כמו סקיצות במחברת של אמן מוכשר וחולמני. יש בו גיטרות אקוסטיות, פסנתר, צ׳לו, קרן יער, מפוחית, תופים פשוטים וצלילים אלקטרוניים מוזרים, וקולו של גוף, רך ומעט חנוק, שמזכיר את ניק דרייק ואת קאט סטיבנס. The Shining, שפותח את האלבום, נפתח בצ׳לו ובקרן יער, והוא שיר יפה ומרגש על התחלה חדשה. Once Around the Block הוא שיר פופ קליל ושמח עם גיטרה אקוסטית ושריקות. Disillusion הוא שיר קצבי ומקפיץ, עם פסנתר ותופים, על מי שמנסה לברוח מאכזבה.''',
'''הצלחת האלבום הובילה את גוף לכתוב את הפסקול לסרט "על אודות בן" עם יו גרנט, שגם הוא זכה להצלחה גדולה. The Hour of Bewilderbeast נשאר אחד מאלבומי הבכורה המקסימים של הפופ הבריטי של תחילת שנות האלפיים.''',
'''שמעו את The Shining, ושימו לב לקרן היער ולצ׳לו בפתיחה. ואם אהבתם את Five Leaves Left של ניק דרייק (אלבום 149), תמצאו כאן רוח קרובה.''',
], [
('The Shining', 'צ׳לו וקרן יער, שיר יפה ומרגש על התחלה חדשה.'),
('Once Around the Block', 'פופ קליל ושמח, עם גיטרה אקוסטית ושריקות.'),
('Disillusion', 'שיר קצבי ומקפיץ, עם פסנתר ותופים, על בריחה מאכזבה.'),
])

add(914, [
'''PJ הארווי, הזמרת והגיטריסטית האנגלייה שהתפרסמה עם אלבומים פרועים וכועסים כמו Dry (אלבום 732) ו־Rid of Me (אלבום 744), בילתה ב־1999 חצי שנה בניו יורק. העיר הגדולה, האנרגיה שלה ואהבה חדשה שינו את המוזיקה שלה. Stories from the City, Stories from the Sea, שיצא בסתיו 2000, הוא האלבום הנגיש, המלודי והאופטימי ביותר שלה, ובשנה שאחריה הוא זכה בפרס מרקורי, והיא הייתה האישה הראשונה שזכתה בו. ביום הטקס היא שהתה בוושינגטון, שם חוותה את פיגועי 11 בספטמבר מקרוב.''',
'''המוזיקה היא רוק גיטרות נקי וחזק, עם מלודיות גדולות, פסנתר, תופים מקפיצים וקולה של הארווי, שעובר בין שירה רכה לבין צעקה עוצמתית. השירים עוסקים באהבה, בעיר, בתשוקה ובחיפוש אחרי בית. Good Fortune הוא שיר רוק שמח וסוחף על אהבה חדשה ועל ריצה ברחובות העיר, עם גיטרה מצלצלת. This Mess We're In הוא דואט לילי ויפה עם תום יורק מרדיוהד, שמספר על זוג בדירה בניו יורק, בזמן שהעיר רועשת מסביב. This Is Love הוא שיר רוק מחוספס ומקפיץ, עם ריף גיטרה פשוט וחזק, על תשוקה שאי אפשר לעצור.''',
'''Stories from the City, Stories from the Sea נחשב לאחד האלבומים הטובים של הארווי, והראה שהיא יכולה להיות גם שמחה ונגישה בלי לאבד את העוצמה שלה. היא המשיכה להפתיע, ובהמשך הפכה לאמנית הראשונה שזכתה פעמיים בפרס מרקורי.''',
'''שמעו את This Mess We're In, ושימו לב לשני הקולות. והשוו את Good Fortune ל־Rid of Me (אלבום 744), כדי לשמוע כמה הארווי השתנתה.''',
], [
('Good Fortune', 'רוק שמח וסוחף על אהבה חדשה ועל ריצה ברחובות העיר.'),
("This Mess We're In", 'דואט לילי ויפה עם תום יורק, על זוג בדירה בניו יורק.'),
('This Is Love', 'רוק מחוספס ומקפיץ, עם ריף גיטרה פשוט וחזק.'),
])

add(915, [
'''אריקה באדו מדאלאס שבטקסס הייתה אחת הדמויות המרכזיות של הניאו סול, יחד עם דיאנג׳לו (אלבום 803) ומקסוול (אלבום 823). אלבום הבכורה שלה, ב־1997, זכה בגראמי, והקול שלה, שמזכיר את בילי הולידיי, הפך למוכר בכל העולם. Mama's Gun, האלבום השני שלה, יצא בסוף 2000, והוקלט באולפן שהקים פעם ג׳ימי הנדריקס בניו יורק, יחד עם קבוצה של מוזיקאים צעירים ומבריקים שכינו את עצמם "סולקווריאנס", ביניהם המתופף קווסטלאב, המפיק ג׳יי דילה ודיאנג׳לו עצמו.''',
'''המוזיקה חמה, חופשית וג׳אזית, עם נגינה חיה: בס עמוק, תופים רכים ומדויקים, פסנתר חשמלי, כלי נשיפה וויברפון, וקולה של באדו, שיכול להיות מצחיק, חכם, כועס או שבור לב. השירים עוסקים באהבה, בעצמאות, בבריאות נפשית ובחברה. Bag Lady, הלהיט הגדול, הוא שיר חכם ונינוח שקורא לנשים להשתחרר מ"התיקים" הרגשיים שהן סוחבות מאהבות קודמות. Didn't Cha Know, שהפיק ג׳יי דילה, הוא שיר רך ומלנכולי, עם קצב חם ומקפיץ. Green Eyes, שסוגר את האלבום, הוא יצירה של כעשר דקות בשלושה חלקים, על פרידה כואבת מאהבה גדולה, שעוברת מג׳אז ישן לבלדה שבורה.''',
'''Mama's Gun נחשב לאחד האלבומים הטובים של הניאו סול, והשפיע על זמרות רבות. רבים רואים בו את האלבום האישי והעמוק ביותר של באדו, שהמשיכה להיות אחת האמניות המקוריות והמסתוריות של המוזיקה האמריקאית.''',
'''שמעו את Green Eyes ברצף, ושימו לב איך השיר עובר מחלק לחלק. והשוו ל־Brown Sugar של דיאנג׳לו (אלבום 803), חבר לאותה משפחה מוזיקלית.''',
], [
('Bag Lady', 'שיר חכם ונינוח, קריאה לנשים להשתחרר מהמטען הרגשי.'),
("Didn't Cha Know", 'שיר רך ומלנכולי, עם קצב חם שהפיק ג׳יי דילה.'),
('Green Eyes', 'יצירה של עשר דקות בשלושה חלקים, על פרידה כואבת.'),
])

add(916, [
'''קולדפליי נולדה בסוף שנות התשעים, כשארבעה סטודנטים מאוניברסיטת לונדון, הזמר והפסנתרן כריס מרטין, הגיטריסט ג׳וני באקלנד, הבסיסט גאי בריימן והמתופף וויל צ׳מפיון, התחילו לנגן יחד. Parachutes, אלבום הבכורה שלהם, יצא בקיץ 2000, הגיע למקום הראשון במצעד הבריטי, זכה בגראמי לאלבום האלטרנטיבי הטוב ביותר, ונמכר במיליוני עותקים. זו הייתה ההתחלה של אחת הלהקות המצליחות ביותר במאה העשרים ואחת.''',
'''הצליל עדין, מלנכולי וחם: גיטרות אקוסטיות וחשמליות נקיות, פסנתר, תופים רכים, וקולו הגבוה והפגיע של מרטין, שעובר בקלות לפלסט. ההשפעה של ג׳ף באקלי (אלבום 779) ושל טראוויס (אלבום 885) ברורה, אבל יש לקולדפליי מלודיות משלהם, פשוטות ומרגשות. Yellow, הלהיט הגדול, הוא שיר אהבה שמשי ופשוט, עם גיטרה גדולה ופזמון על כוכבים שזוהרים בצהוב. לפי הסיפור, מרטין כתב אותו כשהביט בכוכבים מחוץ לאולפן בוויילס. Trouble הוא בלדה שקטה ויפה עם פסנתר, על מי שמבקש סליחה על שפגע במישהו שהוא אוהב. Shiver, שבו מרטין נשמע הכי קרוב לג׳ף באקלי, הוא שיר אהבה נואש ומרגש, עם גיטרה מצלצלת.''',
'''Parachutes נחשב בעיני רבים לאלבום הכן והאינטימי ביותר של קולדפליי, לפני שהם הפכו ללהקת אצטדיונים ענקית עם להיטים אינספור. הוא נשמע כמו להקה צעירה שמנגנת בחדר קטן, לפני שהעולם כולו גילה אותה. השירים שלו עדיין מושרים בכל הופעה של הלהקה, ו־Yellow נשאר אחד השירים האהובים שלה.''',
'''שמעו את Yellow ואחר כך את Trouble, שני צדדים של אותה להקה צעירה. והמשיכו ל־A Rush of Blood to the Head (אלבום 948), שיצא שנתיים אחר כך.''',
], [
('Yellow', 'שיר אהבה שמשי ופשוט, עם גיטרה גדולה ופזמון על כוכבים.'),
('Trouble', 'בלדה שקטה ויפה עם פסנתר, בקשת סליחה ממי שאוהבים.'),
('Shiver', 'שיר אהבה נואש ומרגש, עם גיטרה מצלצלת וקול גבוה.'),
])

add(917, [
'''קומון, לוני רשיד לין, הוא ראפר משיקגו, שהתפרסם בשנות התשעים כאחד הקולות החכמים והחושבים של ההיפ הופ, עם מילים על חברה, אהבה, רוחניות ופוליטיקה. Like Water for Chocolate, שיצא באביב 2000, הוקלט בניו יורק עם אותה חבורה של מוזיקאים צעירים, "סולקווריאנס", שעבדה גם עם אריקה באדו (אלבום 915) ודיאנג׳לו: המתופף קווסטלאב מהרוטס והמפיק ג׳יי דילה. השם לקוח מרומן וסרט מקסיקני ידוע, והאלבום הפך להצלחה המסחרית הראשונה של קומון.''',
'''המוזיקה חמה, אורגנית וג׳אזית: תופים חיים ורכים, בס עמוק, פסנתר חשמלי, כלי נשיפה, ודגימות מתקליטי סול וג׳אז ישנים, עם הקצבים המיוחדים של ג׳יי דילה, שנשמעים קצת "מתנדנדים" ולא מדויקים, באופן שהפך לסימן ההיכר שלו. קומון עושה ראפ בקול רגוע וחכם, ולצידו זמרים וזמרות סול. The Light, הלהיט הגדול, הוא שיר אהבה רך ויפה, מעל דגימה של שיר סול ישן, והיה מועמד לגראמי. The 6th Sense, שהפיק DJ פרימייר, הוא שיר קצבי וחד על כוחו של ההיפ הופ. Time Travelin' (A Tribute to Fela) הוא מחווה ארוכה לפלה קוטי (אלבום 232), עם בנו פמי קוטי וכלי נשיפה אפרוביט.''',
'''Like Water for Chocolate נחשב לאחד האלבומים החשובים של ההיפ הופ החושב של תחילת שנות האלפיים, והשפיע על ראפרים רבים שבאו אחריו. קומון המשיך לקריירה ארוכה כראפר וכשחקן, וזכה גם בפרס אוסקר על שיר לסרט.''',
'''שמעו את The Light, ושימו לב לשילוב בין הראפ הרגוע לבין הדגימה החמה. והשוו ל־Mama's Gun של אריקה באדו (אלבום 915), שהוקלט באותו אולפן ועם אותם מוזיקאים.''',
], [
('The Light', 'שיר אהבה רך ויפה, מעל דגימה של שיר סול ישן.'),
('The 6th Sense', 'שיר קצבי וחד על כוחו של ההיפ הופ, בהפקת DJ פרימייר.'),
('Time Travelin\' (A Tribute to Fela)', 'מחווה ארוכה לפלה קוטי, עם בנו פמי וכלי נשיפה אפרוביט.'),
])

add(920, [
'''אחרי ההצלחה של The Slim Shady LP (אלבום 894), אמינם הפך לכוכב עולמי, והתהילה הזאת, עם כל הביקורת, ההערצה וההתנגדות שהגיעו איתה, היא הנושא המרכזי של The Marshall Mathers LP, שיצא באביב 2000. האלבום, שנקרא על שמו האמיתי, נמכר ביותר ממיליון ושבע מאות אלף עותקים באמריקה רק בשבוע הראשון, שיא לאלבום ראפ באותה תקופה, וזכה בגראמי לאלבום הראפ הטוב ביותר. הוא גם עורר סערה ענקית בגלל מילים בוטות, אלימות ופוגעניות.''',
'''הקצבים, חלקם של דוקטור דרה וחלקם של אמינם עצמו, אפלים, מינימליסטיים ומקפיצים, והראפ של אמינם מהיר, מבריק ומלא זעם, הומור שחור וכאב. בחלק מהשירים הוא מדבר כסלים שיידי, הדמות הפרועה שלו, ובחלקם בקולו האמיתי, על ילדותו, על משפחתו ועל הלחץ של התהילה. Stan, השיר המפורסם, הוא סיפור מצמרר בצורת מכתבים של מעריץ אובססיבי, מעל דגימה מתוך שיר עדין של הזמרת דידו, ושמו הפך לכינוי באנגלית למעריץ קיצוני. The Real Slim Shady הוא שיר מצחיק ומתגרה, עם קצב מקפיץ, שהפך ללהיט ענק. The Way I Am הוא שיר זועם ואישי, על הלחץ של המעריצים, התקשורת וחברת התקליטים.''',
'''The Marshall Mathers LP נחשב לאחד מאלבומי ההיפ הופ החשובים והשנויים במחלוקת של כל הזמנים. בטקס הגראמי של 2001 הופיע אמינם עם אלטון ג׳ון, בשיר Stan, הופעה שנתפסה כתשובה לביקורת על המילים שלו.''',
'''שמעו את Stan מתחילתו ועד סופו, והקשיבו לסיפור שנבנה ממכתב למכתב. המילים באלבום קשות ובוטות מאוד.''',
], [
('Stan', 'סיפור מצמרר במכתבים של מעריץ אובססיבי, מעל דגימה של דידו.'),
('The Real Slim Shady', 'שיר מצחיק ומתגרה עם קצב מקפיץ, להיט ענק.'),
('The Way I Am', 'שיר זועם ואישי, על הלחץ של התהילה.'),
])

add(921, [
'''גולדפראפ הם הזמרת אליסון גולדפראפ והמלחין וויל גרגורי. אליסון התחילה את דרכה כזמרת אורחת אצל טריקי (אלבום 788) ואורביטל, ווויל היה נגן ומלחין של מוזיקה לסרטים ולטלוויזיה. כשחתמו בחברת התקליטים מיוט, הם שכרו בית קטן בכפר באנגליה, הסתגרו בו לחודשים, והקליטו שם את Felt Mountain, שיצא בסתיו 2000. האלבום היה מועמד לפרס מרקורי, ונשמע שונה מכל דבר אחר של אותה תקופה.''',
'''המוזיקה קולנועית, אלגנטית ומסתורית, כמו פסקול לסרט ריגול ישן או לאגדה אפלה: כלי מיתר, סינתיסייזרים ישנים, פסנתר, שריקות ותופים איטיים, בהשראת המלחינים ג׳ון בארי, שכתב את המוזיקה לסרטי ג׳יימס בונד, ואניו מוריקונה, וגם הקברט הגרמני של שנות העשרים והשלושים. הקול של אליסון גולדפראפ הוא הכוכב: הוא יכול להיות לוחש ומפתה, גבוה ושקוף כמו זכוכית, או מוזר ומפחיד. Lovely Head, שפותח את האלבום, נפתח בשריקה מסתורית בסגנון מערבון, ומתפתח לשיר ריגול דרמטי. Utopia הוא שיר יפה ומרחף, שבו הקול עולה לגבהים מדהימים. Pilots הוא שיר עדין ויפה, עם כלי מיתר, על טייסים שמרחפים מעל העננים.''',
'''Felt Mountain הפתיע את כל מי ששמע אותו, והפך לאלבום אהוב במיוחד על אוהבי מוזיקה אלגנטית ושקטה. באלבומים הבאים שינו גולדפראפ כיוון לגמרי, והפכו ללהקת פופ אלקטרוני רוקדת וזוהרת, אבל הבכורה נשארה אחד האלבומים המיוחדים ביותר שלהם.''',
'''זה אלבום ללילה, באוזניות, עם כוס יין. התחילו ב־Lovely Head, והקשיבו לשריקה. והשוו ל־Dummy של פורטיסהד (אלבום 760), שגם הוא שאב השראה מפסקולים ישנים.''',
], [
('Lovely Head', 'שריקה מסתורית בסגנון מערבון, שמתפתחת לשיר ריגול דרמטי.'),
('Utopia', 'שיר יפה ומרחף, שבו הקול עולה לגבהים מדהימים.'),
('Pilots', 'שיר עדין עם כלי מיתר, על טייסים שמרחפים מעל העננים.'),
])

add(923, [
'''למבצ׳ופ היא להקה מנאשוויל, בירת מוזיקת הקאנטרי, אבל היא אף פעם לא דמתה ללהקות הקאנטרי של העיר. בראשה עומד קורט וגנר, שבמשך שנים עבד בליטוש רצפות עץ, ושר בקול נמוך, רך וכמעט לוחש. סביבו מנגנת חבורה גדולה של מוזיקאים, לפעמים יותר מעשרה, עם כלי נשיפה, כלי מיתר, גיטרות ותופים, ולכן הלהקה כונתה בצחוק "להקת הקאנטרי המוזרה ביותר בנאשוויל". Nixon, שיצא בתחילת 2000, הוא האלבום שבו הם הגיעו לשיא, ונחשב לטוב ביותר שלהם.''',
'''באלבום הזה למבצ׳ופ חיברו את הקאנטרי האיטי והשקט שלהם עם סול של שנות השבעים, בהשראת קרטיס מייפילד (אלבום 246) ומרווין גיי. וגנר שר כאן הרבה בפלסט גבוה ושביר, מעל כלי מיתר עשירים, כלי נשיפה חמים, פסנתר, גיטרות רכות ולפעמים מקהלת גוספל. המילים מוזרות, מצחיקות ומלאות בפרטים קטנים מחיי היומיום. השם, על שם הנשיא האמריקאי ריצ׳רד ניקסון, רומז לרעיון אבל לא לסיפור ברור, ובחוברת של התקליט אפילו הופיעה רשימת ספרים על ניקסון. The Old Gold Shoe, שפותח את האלבום, הוא שיר רך ויפה עם כלי מיתר. Up with People, שסוגר אותו, הוא שיר גוספל שמח וסוחף, עם מקהלה ותופים, שנבנה לשיא מרומם. You Masculine You הוא שיר איטי ומפתה, בסגנון סול.''',
'''Nixon הפך לאלבום המצליח ביותר של למבצ׳ופ, בעיקר באירופה, ונחשב לאחד היפים של התקופה. הוא הראה שגם בנאשוויל יש מקום למוזיקה אחרת לגמרי.''',
'''שמעו את Up with People, ושימו לב איך שיר שקט הופך לחגיגה. ואם אהבתם את Superfly של קרטיס מייפילד (אלבום 246), השוו לפלסט של וגנר.''',
], [
('The Old Gold Shoe', 'פתיחה רכה ויפה עם כלי מיתר וקול לוחש.'),
('Up with People', 'גוספל שמח וסוחף עם מקהלה, שנבנה לשיא מרומם.'),
('You Masculine You', 'שיר איטי ומפתה בסגנון סול, עם פלסט שביר.'),
])

add(925, [
'''אחרי ההצלחה של Ray of Light (אלבום 868), מדונה המשיכה לחפש צלילים חדשים. Music, שיצא בסתיו 2000, נעשה יחד עם ויליאם אורביט, שוב, ועם מפיק צרפתי בשם מירוואיס, שהביא צליל אלקטרוני חד, מוזר ומשחקי, בהשראת המוזיקה האלקטרונית הצרפתית של אותן שנים, כמו דאפט פאנק (אלבום 850). מדונה, שבדיוק נולד לה בנה השני, אימצה לאלבום דימוי של קאובוי, עם כובע בוקרים ומגפיים. השיר שנתן לאלבום את שמו הגיע למקום הראשון במצעד האמריקאי ובמקומות רבים בעולם.''',
'''המוזיקה מחברת פופ אלקטרוני מקפיץ עם גיטרות אקוסטיות, צלילים מעובדים ומקוטעים, קולות רובוטיים ומעבר חד בין רעש לשקט. מירוואיס אהב לחתוך צלילים, לעצור אותם פתאום ולשחק בהם, ויצר צליל שנשמע מודרני גם היום. Music, שיר הפתיחה, הוא שיר ריקוד שמח ופשוט, על הקסם של המוזיקה שמחברת בין אנשים, עם קצב מקפיץ וקול מעובד. Don't Tell Me, אולי השיר הטוב באלבום, בנוי על גיטרה אקוסטית שנחתכת ונעצרת שוב ושוב, כאילו התקליט נתקע, ומעליה מלודיה עצובה ויפה. What It Feels Like for a Girl הוא שיר שקט ומהורהר על הציפיות מבנות ומנשים.''',
'''Music היה אחד האלבומים המצליחים של מדונה, והראה שוב שהיא יודעת לעבוד עם המפיקים הנכונים ולהקדים את זמנה. הצליל החתוך והמשחקי שלו השפיע על הפופ של תחילת שנות האלפיים.''',
'''שמעו את Don't Tell Me, ושימו לב לגיטרה שנעצרת ונחתכת. והשוו את Music ל־Ray of Light (אלבום 868), כדי לשמוע כמה מדונה השתנתה בשנתיים.''',
], [
('Music', 'שיר ריקוד שמח ופשוט על הקסם של המוזיקה, עם קול מעובד.'),
("Don't Tell Me", 'גיטרה אקוסטית שנחתכת שוב ושוב, ומעליה מלודיה עצובה ויפה.'),
('What It Feels Like for a Girl', 'שיר שקט ומהורהר על הציפיות מבנות ומנשים.'),
])

add(926, [
'''דה אבלנשז היא קבוצה ממלבורן שבאוסטרליה, שהתחילה בסוף שנות התשעים כלהקת פאנק היפ הופ פרועה, והפכה לפרויקט של שני מפיקים, רובי צ׳ייטר ודארן זלטמן, שאספו אלפי תקליטים ישנים מחנויות יד שנייה. Since I Left You, אלבום הבכורה שלהם, יצא באוסטרליה בסוף 2000, ובשאר העולם ב־2001. הוא בנוי כולו מדגימות, לפי ההערכות יותר משלושת אלפים וחמש מאות קטעים קצרים מתקליטים של אחרים, והוא נשמע כמו משהו שלא נשמע קודם.''',
'''האלבום עובר כמו מסע אחד ארוך, בלי הפסקות, כמו סט של תקליטן או כמו טיול לאי טרופי מדומיין: דיסקו, סול, פופ של שנות השישים, מוזיקת אקזוטיקה, היפ הופ, צלילים של סרטים וקולות של אנשים, הכל מחובר בעדינות לשלם שמח, נוסטלגי ומצחיק. Since I Left You, שפותח את האלבום, בנוי על לחש של זמרות משנות השישים, כלי מיתר וקצב דיסקו רך, והוא מרגיש כמו חופשה בגן עדן. Frontier Psychiatrist הוא קטע מטורף ומצחיק, שבנוי מדיאלוגים של מערכון קומי ישן, קולות של בעלי חיים ותזמורת מקסיקנית, וכל זה רוקד. Electricity הוא שיר שמח ומקפיץ, עם קול נשי מתוק וקצב דיסקו.''',
'''Since I Left You נחשב לאחד האלבומים הגדולים של מוזיקת הדגימות, לצד Endtroducing של די ג׳יי שאדו (אלבום 815). קבלת האישורים לכל הדגימות הייתה משימה ענקית, ואחת מהן הגיעה ממדונה עצמה. האלבום הבא שלהם הגיע רק שש עשרה שנים אחר כך.''',
'''שמעו את האלבום כולו ברצף, כמו נסיעה, ונסו לזהות כמה שיותר מהקטעים המוכרים שמסתתרים בו. התחילו ב־Frontier Psychiatrist, כדי לצחוק.''',
], [
('Since I Left You', 'לחש של זמרות משנות השישים וקצב דיסקו רך, כמו חופשה בגן עדן.'),
('Frontier Psychiatrist', 'קטע מטורף ומצחיק, מדיאלוגים של מערכון ישן ותזמורת מקסיקנית.'),
('Electricity', 'שיר שמח ומקפיץ, עם קול נשי מתוק וקצב דיסקו.'),
])

add(927, [
'''אאוטקאסט הם שני חברים מאטלנטה שבג׳ורג׳יה, אנדרה 3000 וביג בוי, שנפגשו בתיכון והפכו את ההיפ הופ של הדרום האמריקאי, שבמשך שנים נחשב פחות רציני מזה של ניו יורק ולוס אנג׳לס, לאחד המקוריים והמשפיעים בעולם. Stankonia, האלבום הרביעי שלהם, יצא בסתיו 2000, וזכה בגראמי לאלבום הראפ הטוב ביותר. שם האלבום לקוח ממקום דמיוני שבו, לפי השניים, אפשר לבטא את עצמך בחופשיות מלאה.''',
'''המוזיקה פרועה, צבעונית ומלאת הפתעות: פאנק בסגנון פרליאמנט ופאנקדליק (אלבום 360), רוק, גוספל, סול, אלקטרו, ואפילו קצבים מהירים של דראם אנד בייס, והכל עם הומור, דמיון ואנרגיה עצומה. שני הראפרים שונים מאוד: אנדרה מוזר, אקספרימנטלי ושר, וביג בוי חד, מהיר ומחובר לרחוב, ויחד הם משלימים זה את זה. Ms. Jackson, הלהיט הגדול, הוא שיר בקשת סליחה מאמה של בת זוג לשעבר, שלפי הדיווחים נכתב על הפרידה של אנדרה מאריקה באדו (אלבום 915), והוא הגיע למקום הראשון במצעד האמריקאי. B.O.B. (Bombs Over Baghdad) הוא שיר מהיר במיוחד ופרוע, עם גיטרות, מקהלת גוספל וקצב שלא נעצר. So Fresh, So Clean הוא שיר רגוע ומפתה, בסגנון סול של שנות השבעים.''',
'''Stankonia נחשב לאחד מאלבומי ההיפ הופ הטובים של כל הזמנים, והראה שהיפ הופ יכול להיות גם ניסיוני וגם מצליח מאוד. האלבום הבא של הצמד היה אלבום כפול, שזכה בגראמי לאלבום השנה.''',
'''שמעו את B.O.B. בקול רם, ושימו לב למהירות ולמקהלה. והשוו ל־Mothership Connection של פרליאמנט (אלבום 360), כדי לשמוע מאיפה הגיע הפאנק שלהם.''',
], [
('Ms. Jackson', 'בקשת סליחה מאמה של בת זוג לשעבר, להיט שהגיע למקום הראשון.'),
('B.O.B. (Bombs Over Baghdad)', 'שיר מהיר ופרוע, עם גיטרות, מקהלת גוספל וקצב שלא נעצר.'),
('So Fresh, So Clean', 'שיר רגוע ומפתה, בסגנון סול של שנות השבעים.'),
])

add(928, [
'''Amnesiac, שיצא באמצע 2001, שמונה חודשים בלבד אחרי Kid A (אלבום 909), הוקלט באותן הקלטות בדיוק. רדיוהד הקליטו כל כך הרבה חומר, שהחליטו לחלק אותו לשני אלבומים, ורבים חשבו בהתחלה שזה יהיה אוסף של שאריות. אבל Amnesiac הוא אלבום שעומד לגמרי בפני עצמו, אפל, מוזר ויפה, וכמה מהשירים הטובים ביותר של הלהקה נמצאים דווקא בו. הוא הגיע למקום הראשון במצעד הבריטי ולמקום השני במצעד האמריקאי.''',
'''כמו ב־Kid A, יש כאן מוזיקה אלקטרונית, תופים מכניים, צלילים מעובדים וקול מקוטע, אבל יש גם יותר גיטרות, יותר פסנתר וכלי מיתר, ואפילו ג׳אז של ניו אורלינס. Pyramid Song, אחד השירים היפים של רדיוהד, הוא שיר עם פסנתר וכלי מיתר, בקצב מוזר ונודד, שקשה לספור, על מסע של נשמות אחרי המוות על נהר. Knives Out הוא שיר גיטרה רך ומלודי יותר, שמזכיר את רדיוהד של OK Computer (אלבום 837), אבל המילים בו אפלות ומצחיקות. Life in a Glasshouse, שסוגר את האלבום, הוקלט עם להקת ג׳אז בריטית ותיקה, ונשמע כמו לוויה ג׳אזית בניו אורלינס, עם חצוצרה וקלרינט עצובים.''',
'''Amnesiac נחשב היום לאחד האלבומים החשובים של רדיוהד, ורבים אוהבים אותו אפילו יותר מ־Kid A. ב־2021 יצאו שני האלבומים יחד במהדורה משותפת, כמו שתי חצאים של יצירה אחת.''',
'''שמעו את Pyramid Song באוזניות, ונסו לספור את הקצב. ואחר כך השוו את Amnesiac ל־Kid A (אלבום 909), ובחרו איזה מהשניים אהוב עליכם יותר.''',
], [
('Pyramid Song', 'פסנתר וכלי מיתר בקצב מוזר ונודד, על מסע של נשמות.'),
('Knives Out', 'שיר גיטרה רך ומלודי, עם מילים אפלות.'),
('Life in a Glasshouse', 'לוויה ג׳אזית בסגנון ניו אורלינס, עם חצוצרה וקלרינט.'),
])

add(929, [
'''סילבר ג׳וז היא להקה שהקים דייוויד ברמן, משורר אמריקאי שכתב שירים מצחיקים, עצובים וחכמים במיוחד, יחד עם חבריו מהלהקה פייבמנט (אלבום 707), בסוף שנות השמונים. ברמן שר בקול בריטון עמוק, יבש וכמעט מדבר, והמילים שלו נחשבות לאחד הדברים היפים בפולק והרוק האמריקאי העצמאי. Bright Flight, שיצא ב־2001, הוקלט בנאשוויל, שאליה עבר ברמן, והוא האלבום הקאנטרי ביותר של הלהקה, עם גיטרת סטיל, כינור ואשתו קאסי, ששרה לצידו.''',
'''המוזיקה פשוטה, רגועה ונינוחה, כמו להקת קאנטרי ותיקה שמנגנת בבר שקט: גיטרות אקוסטיות וחשמליות, גיטרת סטיל מייבבת, תופים עדינים ובס. אבל המילים מוזרות, מבריקות ומלאות בתמונות מפתיעות, שגורמות לצחוק ולעצב באותו משפט. Time Will Break the World הוא שיר עצוב ויפה, על הזמן ששובר הכל, עם מלודיה איטית וגיטרת סטיל. Tennessee הוא דואט מתוק עם אשתו, על אהבה ועל המדינה שבה גרו, ויש בו חום והומור. Room Games and Diamond Rain הוא שיר מהורהר, עם תמונות חלומיות ומלודיה נוגה.''',
'''סילבר ג׳וז אף פעם לא הייתה להקה מפורסמת, אבל היא אהובה מאוד על כותבי שירים ומוזיקאים, ורבים רואים בברמן אחד מכותבי המילים הגדולים של דורו. ברמן מת ב־2019, אחרי שנים של מאבק בדיכאון, זמן קצר אחרי שהוציא אלבום חדש. השירים שלו ממשיכים לרגש מאזינים חדשים, ורבים מגלים אותם רק עכשיו.''',
'''הקשיבו למילים, כי הן העיקר כאן. התחילו ב־Tennessee, ואם אהבתם את I See a Darkness של בוני "פרינס" בילי (אלבום 897), תמצאו כאן נשמה קרובה.''',
], [
('Time Will Break the World', 'שיר עצוב ויפה על הזמן ששובר הכל, עם גיטרת סטיל.'),
('Tennessee', 'דואט מתוק עם אשתו, על אהבה ועל המדינה שבה גרו.'),
('Room Games and Diamond Rain', 'שיר מהורהר, עם תמונות חלומיות ומלודיה נוגה.'),
])

add(930, [
'''ביורק, הזמרת האיסלנדית שהתחילה את דרכה בלהקת השוגרקיובס (אלבום 631) והפכה לכוכבת עולמית עם Debut (אלבום 749), תמיד הפתיעה עם כל אלבום. אחרי אלבומים רועשים וקצביים, Vespertine, שיצא בקיץ 2001, היה אלבום שקט, אינטימי וחורפי, כמו לחישה בחדר סגור. היא הקליטה אותו בתקופה של אהבה חדשה, והוא כולו עוסק בעולם הפנימי, ברוך, בתשוקה ובפרטיות. רבים רואים בו את האלבום היפה ביותר שלה.''',
'''הצליל עשוי מדברים קטנים ועדינים: נבל, קופסאות נגינה, כלי מיתר, מקהלה מגרינלנד וקצבים שנבנו מצלילים זעירים, כמו קלפים שמערבבים, קרח שנשבר או צעדים בשלג. ביורק עבדה עם צמד מוזיקאים אלקטרוניים מסן פרנסיסקו, שהתמחו בהפיכת רעשים קטנים לקצב. הקול שלה עובר מלחישה לצעקה, אבל תמיד נשאר חם וקרוב. Hidden Place, שפותח את האלבום, הוא שיר יפה ומרחף על מקום סודי של שני אוהבים, עם מקהלה וכלי מיתר. Pagan Poetry הוא שיר דרמטי וחושני, עם נבל וקופסת נגינה, שנבנה לשיא מרגש. Cocoon הוא שיר שקט מאוד, כמעט לחישה, על אינטימיות.''',
'''Vespertine נחשב לאחד האלבומים החשובים של ביורק, והראה שמוזיקה אלקטרונית יכולה להיות גם עדינה, אישית וחמה. באותה תקופה היא הופיעה בטקס האוסקר בשמלת ברבור מפורסמת, ששמה נשאר מזוהה איתה. ההופעות שלה באותה תקופה, עם נבל, מקהלה ותזמורת קטנה, נערכו בבתי אופרה ובאולמות קונצרטים, כדי לשמור על האינטימיות.''',
'''שמעו את Vespertine בחורף, בשקט ובאוזניות, כדי לשמוע את כל הצלילים הקטנים. והשוו את Hidden Place ל־Human Behaviour מ־Debut (אלבום 749).''',
], [
('Hidden Place', 'שיר יפה ומרחף על מקום סודי של שני אוהבים, עם מקהלה.'),
('Pagan Poetry', 'שיר דרמטי וחושני עם נבל וקופסת נגינה, שנבנה לשיא.'),
('Cocoon', 'שיר שקט מאוד, כמעט לחישה, על אינטימיות.'),
])

add(931, [
'''גורילז היא להקה וירטואלית: ארבעה חברים מצוירים, בדמויות קומיקס, שמאחוריהם עומדים דיימון אלברן, הזמר של בלר (אלבום 836), ואמן הקומיקס ג׳יימי היולט. השניים גרו יחד בדירה בלונדון, צפו ב־MTV, ורצו להגיב על התעשייה המלאכותית של כוכבי הפופ. הם המציאו את הזמר 2־די, הבסיסט מרדוק, המתופף ראסל והגיטריסטית היפנית נודל, שאיש לא ראה אף פעם בבשר ודם. Gorillaz, אלבום הבכורה, יצא באביב 2001, ונמכר במיליוני עותקים.''',
'''את המוזיקה הפיק דן דה אוטומייטור, שעבד קודם על Dr. Octagonecologyst (אלבום 810), והיא מחברת היפ הופ, דאב, פאנק, רוק, פופ ומוזיקה לטינית, עם הקול המנומנם והעייף של אלברן, ראפרים אורחים ושלל צלילים מוזרים. Clint Eastwood, הלהיט הגדול, הוא שיר נינוח ומעט מפחיד, עם מלודיקה, קצב היפ הופ איטי, הפזמון השקט של אלברן והראפ של דל דה פאנקי הומוספיין. 19-2000 הוא שיר קופצני ושמח, עם צלילים אלקטרוניים ופזמון שנדבק. Tomorrow Comes Today הוא שיר מלנכולי ויפה, עם מלודיקה וקצב רגוע, על עולם שמתקדם מהר מדי.''',
'''גורילז הפכה לאחת הלהקות המצליחות של שנות האלפיים, וספר השיאים של גינס הכריז עליה כלהקה הווירטואלית המצליחה ביותר. אלברן המשיך לעבוד איתה במשך עשרות שנים, עם אורחים מכל העולם, ובמקביל לבלר ולפרויקטים רבים נוספים. החיבור בין מוזיקה, קומיקס ואנימציה היה חדש מאוד, והקליפים המצוירים שלהם הפכו לחלק מרכזי מהחוויה.''',
'''שמעו את Clint Eastwood, ושימו לב לשילוב בין הקול העייף של אלברן לבין הראפ. והשוו ל־Blur (אלבום 836), כדי לשמוע כמה רחוק הלך אלברן בארבע שנים.''',
], [
('Clint Eastwood', 'שיר נינוח ומעט מפחיד, עם מלודיקה וראפ של אורח.'),
('19-2000', 'שיר קופצני ושמח, עם צלילים אלקטרוניים ופזמון שנדבק.'),
('Tomorrow Comes Today', 'שיר מלנכולי ויפה, על עולם שמתקדם מהר מדי.'),
])

add(932, [
'''שנה אחרי Heartbreaker (אלבום 904), השקט והשבור, ראיין אדמס הוציא את Gold, אלבום גדול, מלוטש ושאפתני יותר, עם להקה מלאה, כלי נשיפה, כלי מיתר וקולות רקע. הוא הקליט אותו בלוס אנג׳לס, והושפע מהרוק הקלאסי של שנות השבעים: הרולינג סטונז, ואן מוריסון, אלטון ג׳ון וניל יאנג. האלבום יצא בסתיו 2001, היה מועמד לכמה פרסי גראמי, והפך את אדמס לשם מוכר בקהל רחב בהרבה. (על הטענות נגדו בשנים מאוחרות יותר, ראו את אלבום 904.)''',
'''המוזיקה עוברת בין שירי רוק סוחפים, בלדות רכות ושירי קאנטרי וסול, וקולו של אדמס נשמע כאן בטוח, חם ומחוספס. השירים עוסקים באהבה, בערים, בגעגועים ובחיים בדרכים. New York, New York, שפותח את האלבום, הוא שיר רוק שמח ומלא אנרגיה, מכתב פרידה ואהבה לעיר. הקליפ שלו צולם ממש ליד מגדלי התאומים ארבעה ימים לפני פיגועי 11 בספטמבר, והפך מאוחר יותר למסמך עצוב ומרגש. When the Stars Go Blue היא בלדה יפה ונוגה, שזמרים רבים הקליטו אחריו. La Cienega Just Smiled הוא שיר שקט ומלנכולי על לילה בלוס אנג׳לס ועל אהבה שהולכת ומתרחקת.''',
'''Gold היה האלבום המצליח ביותר של אדמס, והראה שהוא יכול לכתוב גם שירי רוק גדולים, לא רק בלדות שקטות. הוא המשיך להוציא אלבומים בקצב מטורף, בכל סגנון אפשרי.''',
'''שמעו את New York, New York, ודמיינו את העיר רגע לפני שהשתנתה. והשוו את Gold ל־Heartbreaker (אלבום 904), שני צדדים של אותו כותב.''',
], [
('New York, New York', 'רוק שמח ומלא אנרגיה, מכתב פרידה ואהבה לעיר.'),
('When the Stars Go Blue', 'בלדה יפה ונוגה, שזמרים רבים הקליטו אחריו.'),
('La Cienega Just Smiled', 'שיר שקט ומלנכולי על לילה בלוס אנג׳לס.'),
])

add(933, [
'''דסטיניז צ׳יילד הייתה להקת בנות מיוסטון שבטקסס, שהחלה כשהחברות היו ילדות, ובראשה עמדה ביונסה נואלס, שאביה היה המנהל של הלהקה. בשנת 2000 שתיים מהחברות עזבו בסערה, הוחלפו, והעיתונות צחקה שהלהקה דומה לתוכנית הריאליטי "הישרדות", שבה מתמודדים מודחים אחד אחרי השני. ביונסה לקחה את הבדיחה והפכה אותה לשם האלבום ולשיר מנצח: Survivor, שיצא באביב 2001, נכנס ישר למקום הראשון במצעד האמריקאי, והפך את השלישייה, ביונסה, קלי רולנד ומישל וויליאמס, לכוכבות עולמיות.''',
'''המוזיקה היא רית׳ם אנד בלוז ופופ של תחילת שנות האלפיים: קצבים חדים ומקפיצים, בס עמוק, הרמוניות קוליות מדויקות ומהירות, וקולה החזק והגמיש של ביונסה, שגם כתבה והפיקה חלק גדול מהשירים. המילים עוסקות בעצמאות נשית, בכוח ובביטחון עצמי. Survivor, השיר שנתן לאלבום את שמו, הוא המנון חזק ודרמטי על מי ששרדה את מי שניסה לשבור אותה, והוא זכה בגראמי. Bootylicious הוא שיר מצחיק ומקפיץ, שבנוי על ריף גיטרה של סטיבי ניקס, והמילה שהמציאו בו נכנסה למילון האנגלי. Independent Women Part I, שנכתב לסרט "המלאכיות של צ׳רלי", הוא המנון של עצמאות כלכלית לנשים.''',
'''Survivor היה האלבום המצליח ביותר של דסטיניז צ׳יילד, ונמכר ביותר מעשרה מיליון עותקים. כמה שנים אחר כך ביונסה פתחה בקריירת סולו, והפכה לאחת האמניות הגדולות והמשפיעות בעולם.''',
'''שמעו את Survivor, ושימו לב לקולות שמחליפים זה את זה. ואם אהבתם את Supa Dupa Fly של מיסי אליוט (אלבום 839), תמצאו כאן את אותם קצבים חדים.''',
], [
('Survivor', 'המנון חזק ודרמטי על מי ששרדה את מי שניסה לשבור אותה.'),
('Bootylicious', 'שיר מצחיק ומקפיץ, על ריף גיטרה של סטיבי ניקס.'),
('Independent Women, Pt. 1', 'המנון של עצמאות כלכלית לנשים, מסרט "המלאכיות של צ׳רלי".'),
])

add(934, [
'''הסטרוקס הם חמישה צעירים מניו יורק, רובם מבתים אמידים ובתי ספר פרטיים, שבסוף שנות התשעים התחילו לנגן רוקנרול פשוט, חד ומהיר, בסגנון הוולווט אנדרגראונד (אלבום 91) וטלוויז׳ן (אלבום 388), בתקופה שבה הרדיו היה מלא בנו מטאל ובפופ. Is This It, אלבום הבכורה שלהם, יצא באמצע 2001, תחילה בבריטניה ובאוסטרליה ורק אחר כך באמריקה, והפך מיד לאחד האלבומים המדוברים ביותר של התקופה. מגזיני מוזיקה כינו אותם "המושיעים של הרוקנרול".''',
'''הצליל פשוט ומדויק: שתי גיטרות שמשתלבות זו בזו כמו שיחה, בס קופצני, תופים יבשים וחדים כמו מכונת תופים, והקול של ג׳וליאן קזבלנקס, שמוקלט כאילו הוא שר דרך טלפון ישן, עייף, מחוספס ומעט משועמם. כל השירים קצרים, והאלבום כולו נמשך פחות משלושים וחמש דקות. Last Nite, הלהיט הגדול, הוא שיר מקפיץ ושמח עם ריף גיטרה פשוט ובלתי נשכח. Someday הוא שיר נוסטלגי ומתוק, על חברות ועל ימים טובים שעברו. Is This It, שפותח את האלבום, הוא שיר נינוח ועייף, עם קצב רגוע ובס שמוביל אותו. אחרי פיגועי 11 בספטמבר הוחלף בגרסה האמריקאית שיר אחד, שעסק בשוטרי ניו יורק, בשיר אחר.''',
'''Is This It פתח גל שלם של להקות רוק גיטרות חדשות, באמריקה ובבריטניה, והחזיר את הרוקנרול לאופנה. הוא נבחר שוב ושוב לאחד האלבומים החשובים של שנות האלפיים.''',
'''שמעו את Last Nite, ושימו לב לשתי הגיטרות שמשלימות זו את זו. והשוו ל־Marquee Moon של טלוויז׳ן (אלבום 388), ניו יורק עשרים וארבע שנים קודם.''',
], [
('Last Nite', 'שיר מקפיץ ושמח, עם ריף גיטרה פשוט ובלתי נשכח.'),
('Someday', 'שיר נוסטלגי ומתוק, על חברות ועל ימים טובים שעברו.'),
('Is This It', 'פתיחה נינוחה ועייפה, עם קצב רגוע ובס שמוביל.'),
])

add(935, [
'''גיליאן וולש גדלה בלוס אנג׳לס, בתם המאומצת של שני כותבים לטלוויזיה, אבל התאהבה במוזיקה העממית הישנה של הרי האפלצ׳ים, בלוגראס, קאנטרי ישן ושירי עם. בקולג׳ היא פגשה את דייוויד רולינגס, גיטריסט וזמר, שהפך לשותף שלה במוזיקה ובחיים, ומאז הם מנגנים יחד, שניים בלבד, עם שתי גיטרות ושני קולות. Time (The Revelator), שיצא ב־2001, היה האלבום הראשון שלהם בחברת תקליטים משלהם, והוקלט באולפן הישן והמפורסם של RCA בנאשוויל, שבו הקליט פעם אלביס פרסלי.''',
'''המוזיקה פשוטה מאוד: שתי גיטרות אקוסטיות, וקולותיהם של וולש ורולינגס בהרמוניה צמודה וחמה. הגיטרה של רולינגס מנגנת מלודיות מתפתלות ומפתיעות, והשירים איטיים, ארוכים ומהפנטים, ומרגישים עתיקים וחדשים בבת אחת. השירים עוסקים בהיסטוריה האמריקאית, בחלומות, באובדן ובמוזיקה עצמה. Revelator, שפותח את האלבום, הוא שיר ארוך ומהפנט, עם גיטרה מתפתלת, על אמת ועל אשליה. Everything Is Free הוא שיר שקט ועצוב, שנכתב על הימים שבהם מוזיקה התחילה להיות מורדת בחינם מהאינטרנט, ועל מוזיקאים שממשיכים לשיר בכל זאת. Elvis Presley Blues הוא שיר יפה ומרגש לזכרו של אלביס, ששר על מותו ועל הקסם שלו.''',
'''Time (The Revelator) נחשב לאחד האלבומים החשובים של האמריקנה, והשפיע על זמרים רבים שחיפשו את השורשים של המוזיקה האמריקאית. וולש ורולינגס הופיעו גם בפסקול הסרט "אחי, איפה אתה?", שהביא את המוזיקה הזאת לקהל עצום.''',
'''זה אלבום לשעות השקטות של הלילה. שמעו את I Dream a Highway, השיר האחרון, שנמשך כרבע שעה, ותנו לו לשאת אתכם. וגם וולש שרה ב־Heartbreaker של ראיין אדמס (אלבום 904).''',
], [
('Revelator', 'שיר ארוך ומהפנט, עם גיטרה מתפתלת, על אמת ועל אשליה.'),
('Everything Is Free', 'שיר שקט ועצוב על מוזיקה בחינם, ועל מי שממשיך לשיר.'),
('Elvis Presley Blues', 'שיר יפה ומרגש לזכרו של אלביס פרסלי.'),
])

add(936, [
'''גוטן פרויקט הם שלושה מוזיקאים שנפגשו בפריז: הצרפתי פיליפ כהן סולאל, השווייצרי כריסטוף מילר והגיטריסט הארגנטינאי אדוארדו מקרוף. השם שלהם הוא משחק מילים: "גוטן" הוא המילה "טנגו" בהיפוך הברות, כמו בסלנג של רחובות בואנוס איירס. הם רצו לקחת את הטנגו, המוזיקה הדרמטית והעצובה של ארגנטינה, ולחבר אותו עם מוזיקה אלקטרונית, דאב וטריפ הופ. La Revancha del Tango, "נקמת הטנגו", יצא ב־2001, ונמכר בכמות גדולה בכל העולם, והביא את הטנגו לבתי קפה, מסעדות ומועדונים.''',
'''המוזיקה איטית, אלגנטית ומלאה ברגש: בנדוניאון, האקורדיון הארגנטינאי, כינורות, פסנתר וגיטרה, יחד עם קצבים אלקטרוניים רגועים, בס עמוק של דאב, דגימות של נאומים וקולות, ושירה בספרדית. התוצאה נשמעת כמו לילה מעושן בבואנוס איירס, רק עם מכונות. Santa María (del Buen Ayre), אולי הקטע המפורסם, הוא טנגו כלי מהפנט, עם בנדוניאון וקצב אלקטרוני חוזר, שנשמע בסרטים ובתוכניות ריקוד. Época הוא קטע רגוע וחלומי, עם כינור ושירה נשית. Last Tango in Paris הוא גרסה מעודכנת לנעימה מפסקול הסרט המפורסם "הטנגו האחרון בפריז".''',
'''La Revancha del Tango פתח גל שלם של "טנגו אלקטרוני", והחזיר עניין בטנגו בקרב צעירים בכל העולם. הוא ממשיך את דרכו של אסטור פיאצולה (אלבום 597), שכבר עשרות שנים קודם חיבר את הטנגו עם ג׳אז ומוזיקה מודרנית.''',
'''שמעו את Santa María (del Buen Ayre), ושימו לב לבנדוניאון מעל הקצב האלקטרוני. והשוו ל־The New Tango של פיאצולה וגארי ברטון (אלבום 597).''',
], [
('Santa María (del Buen Ayre)', 'טנגו כלי מהפנט, עם בנדוניאון וקצב אלקטרוני חוזר.'),
('Época', 'קטע רגוע וחלומי, עם כינור ושירה נשית.'),
('Last Tango in Paris', 'גרסה מעודכנת לנעימה מהסרט "הטנגו האחרון בפריז".'),
])

add(937, [
'''הווייט סטרייפס הם צמד מדטרויט: ג׳ק וייט בגיטרה ובשירה, ומג וייט בתופים. בהתחלה הם הציגו את עצמם כאח ואחות, אבל מאוחר יותר התברר שהם היו בעצם זוג נשוי שהתגרש. הם תמיד לבשו רק אדום, לבן ושחור, וניגנו רק שניים, בלי בס, רוקנרול גס ופשוט שמבוסס על הבלוז הישן. White Blood Cells, האלבום השלישי שלהם, יצא באמצע 2001, הוקלט בממפיס בארבעה ימים בלבד, והפך אותם, יחד עם הסטרוקס (אלבום 934), למובילי הגל החדש של רוק הגראז׳.''',
'''הצליל גולמי, רועש וחי: גיטרה מעוותת וחזקה, תופים פשוטים וכבדים, וקולו הגבוה והחשמלי של ג׳ק וייט. אבל לצד הרוקנרול הפרוע יש גם שירי פולק וקאנטרי מתוקים ושקטים. Fell in Love with a Girl, הלהיט הגדול, הוא שיר רוק מהיר ופרוע של פחות משתי דקות. הקליפ שלו, שבו הצמד בנוי כולו מלגו, הפך למפורסם וזכה בפרסים. Hotel Yorba הוא שיר קאנטרי שמח וקליל, עם גיטרה אקוסטית ומלודיה שנדבקת. We're Going to Be Friends הוא שיר מתוק ותמים, רק גיטרה וקול, על ילדים שמתחילים את שנת הלימודים ונעשים חברים.''',
'''White Blood Cells הפך את הווייט סטרייפס לאחת הלהקות הגדולות של שנות האלפיים. האלבום הבא שלהם כלל את Seven Nation Army, שהריף שלו נשמע עד היום בכל אצטדיון כדורגל. הם הוכיחו שגם שני אנשים עם גיטרה ותופים יכולים להישמע כמו להקה ענקית.''',
'''שמעו את Fell in Love with a Girl בקול רם, ואחר כך את We're Going to Be Friends, שני הקצוות של הצמד. והשוו ל־Now I Got Worry של הבלוז אקספלוז׳ן (אלבום 830), שגם הם ניגנו בלי בס.''',
], [
('Fell in Love with a Girl', 'רוק מהיר ופרוע של פחות משתי דקות, עם קליפ מלגו.'),
('Hotel Yorba', 'שיר קאנטרי שמח וקליל, עם מלודיה שנדבקת.'),
("We're Going to Be Friends", 'שיר מתוק ותמים, רק גיטרה וקול, על חברות של ילדים.'),
])

add(939, [
'''ג׳יי־זי, שון קרטר, גדל בשיכון ציבורי בברוקלין, ובשנות התשעים הפך מסוחר ברחוב לאחד הראפרים והאנשים העשירים בהיפ הופ. The Blueprint, האלבום השישי שלו, יצא ב־11 בספטמבר 2001, ממש ביום הפיגועים בניו יורק, ולמרות זאת נכנס ישר למקום הראשון במצעד האמריקאי. רבים רואים בו את האלבום הטוב ביותר שלו, ואחד מאלבומי ההיפ הופ החשובים של העשור.''',
'''את רוב הקצבים הפיקו שני מפיקים צעירים, ג׳אסט בלייז וקניה ווסט, שהיה אז כמעט לא מוכר. הם בנו את הצליל של האלבום על דגימות של שירי סול ישנים משנות השישים והשבעים, מואצות ומוגבהות, כך שהקולות נשמעים כמו מקהלה חמה ונוסטלגית. מעליהן ג׳יי־זי עושה ראפ בקול רגוע, בטוח ומלא ביטחון, עם חרוזים מבריקים, הומור וכעס. Izzo (H.O.V.A.), הלהיט הגדול, בנוי על דגימה משיר מפורסם של הג׳קסון 5, ושמח וקליל. Takeover הוא שיר זועם ומאיים, שבו ג׳יי־זי תוקף ראפרים יריבים, ובהם נאס (אלבום 762), והוא הפך לחלק מאחד הסכסוכים המפורסמים בהיפ הופ. Song Cry הוא שיר עצוב ואישי, על אהבה שהוא הרס, מעל דגימה סולית יפה.''',
'''The Blueprint השפיע מאוד על הצליל של ההיפ הופ בשנים הבאות, וקניה ווסט, שהפיק חלק ממנו, הפך בעצמו לאחד הראפרים החשובים בעולם. באלבום יש גם שיר משותף עם אמינם (אלבום 894), השיר היחיד באלבום עם ראפר אורח.''',
'''שמעו את Izzo (H.O.V.A.), ונסו לזהות את שיר הג׳קסון 5 המקורי. והשוו את Takeover ל־Illmatic של נאס (אלבום 762), כדי להבין על מה היה הריב.''',
], [
('Izzo (H.O.V.A.)', 'שיר שמח וקליל, על דגימה משיר מפורסם של הג׳קסון 5.'),
('Takeover', 'שיר זועם ומאיים, חלק מאחד הסכסוכים המפורסמים בהיפ הופ.'),
('Song Cry', 'שיר עצוב ואישי על אהבה שנהרסה, מעל דגימה סולית.'),
])

add(940, [
'''רויקסופ הם שני מוזיקאים מצפון נורווגיה, טורביירן ברונדטלנד וסוויין ברגה, שגדלו בטרומסו, עיר קטנה ומרוחקת מעל החוג הארקטי, ועברו לברגן, שבסוף שנות התשעים הייתה בית לסצנה מוזיקלית חדשה ותוססת. Melody A.M., אלבום הבכורה שלהם, יצא ב־2001, והפך להצלחה גדולה באירופה, עם מוזיקה אלקטרונית רכה, שמחה ונוסטלגית, שהתאימה במיוחד לבקרים רגועים ולערבים שקטים.''',
'''הצליל חם ונעים: סינתיסייזרים ישנים, קצבים רכים של היפ הופ והאוס, בס מתגלגל, כלי מיתר, ופה ושם קולות של זמרים אורחים. הכל נשמע כמו נוף צפוני יפה, עם אור של שמש חצות. Eple, שפירוש שמו בנורווגית "תפוח", הוא קטע שמח וקופצני, עם מלודיה מתוקה וסינתיסייזר בוהק, שהפך למוכר מאוד. Poor Leno, עם הזמר ארלנד איה מהצמד הנורווגי קינגס אוף קונוויניינס, הוא שיר אלקטרוני מלנכולי וסוחף, עם בס חזק. Remind Me, גם הוא עם איה, הוא שיר עדין וקליט, והקליפ שלו, שמתאר יום בחייה של אישה באמצעות גרפים ותרשימים, הפך למפורסם.''',
'''Melody A.M. נחשב לאחד האלבומים החשובים של מוזיקת הרגיעה האלקטרונית של תחילת שנות האלפיים, לצד Moon Safari של אייר (אלבום 874). רויקסופ המשיכו להוציא אלבומים מצליחים, והפכו לאחד השמות המוכרים של המוזיקה הנורווגית. הצליל שלהם השפיע על מוזיקאים רבים בסקנדינביה ובעולם, ונשמע מאז בפרסומות ובסרטים רבים.''',
'''שמעו את Eple בבוקר, ואת Poor Leno בערב. והשוו ל־Music Has the Right to Children של בורדס אוף קנדה (אלבום 879), עוד צד נוסטלגי של המוזיקה האלקטרונית של אותה תקופה.''',
], [
('Eple', 'קטע שמח וקופצני, עם מלודיה מתוקה וסינתיסייזר בוהק.'),
('Poor Leno', 'שיר אלקטרוני מלנכולי וסוחף, עם בס חזק וקול רך.'),
('Remind Me', 'שיר עדין וקליט, עם קליפ מפורסם של גרפים ותרשימים.'),
])

add(941, [
'''דרייב־ביי טראקרז היא להקה מאתונה שבג׳ורג׳יה, שהקימו שני חברים מאלבמה, פטרסון הוד ומייק קולי, שגדלו בשנות השבעים בדרום האמריקאי, בין טרקטורים, מפעלים ולינירד סקינירד ברדיו. Southern Rock Opera, שיצא ב־2001 בחברת תקליטים קטנה שלהם, בתקציב קטן מאוד, הוא אלבום כפול ושאפתני: אופרת רוק שמספרת על לינירד סקינירד (אלבום 270), על התרסקות המטוס שבה נהרגו חלק מחבריה ב־1977, ועל מה שהוד מכנה "הכפילות של הדבר הדרומי": הגאווה, הבושה, הגזענות, האהבה והיופי של הדרום.''',
'''המוזיקה היא רוק דרומי כבד ומחוספס, עם שלוש גיטרות חשמליות, כמו אצל לינירד סקינירד, תופים חזקים ושני זמרים שמספרים סיפורים בקול מחוספס ובמבטא דרומי כבד. חלק מהשירים מדברים בקולו של נער שגדל באלבמה, וחלקם מספרים את סיפור הלהקה. Ronnie and Neil מספר על "הריב" המפורסם בין לינירד סקינירד לניל יאנג, שכתב שירים נגד הדרום, וקיבל תשובה בשיר Sweet Home Alabama, ועל הכבוד שהיה בעצם בין השניים. The Southern Thing הוא שיר סוחף על הגאווה והמבוכה של להיות דרומי. Let There Be Rock הוא שיר שמח ומצחיק על נער שהלך להופעות רוק, עם רשימה ארוכה של להקות.''',
'''Southern Rock Opera הפך את דרייב־ביי טראקרז לאחת הלהקות החשובות של הרוק האמריקאי של שנות האלפיים, ונחשב לאחד האלבומים החכמים שנכתבו על הדרום האמריקאי. אחרי ההצלחה הוא הוצא מחדש בחברת תקליטים גדולה.''',
'''שמעו את Ronnie and Neil, ואחר כך את Sweet Home Alabama של לינירד סקינירד, ו־Southern Man של ניל יאנג מ־After the Gold Rush (אלבום 185), כדי להבין את הסיפור.''',
], [
('Ronnie and Neil', 'סיפור "הריב" בין לינירד סקינירד לניל יאנג, ועל הכבוד ביניהם.'),
('The Southern Thing', 'שיר סוחף על הגאווה והמבוכה של להיות דרומי.'),
('Let There Be Rock', 'שיר שמח ומצחיק על נער שהלך להופעות רוק.'),
])

add(942, [
'''סופר פרי אנימלס, הלהקה הוולשית המטורפת והמקורית מ־Fuzzy Logic (אלבום 808), חתמו בתחילת שנות האלפיים בחברת תקליטים גדולה, ו־Rings Around the World, שיצא באמצע 2001, היה האלבום השאפתני ביותר שלהם. הוא היה מהאלבומים הראשונים שיצאו בו זמנית גם כ־DVD, עם צליל היקפי וקליפ לכל אחד מהשירים. בין האורחים יש שני אורחים מפתיעים: פול מקרטני, שהשמיע באחד השירים צלילים של לעיסת סלרי וגזר, וג׳ון קייל מהוולווט אנדרגראונד, שניגן בפסנתר.''',
'''המוזיקה עוברת בין כל הסגנונות: פופ פסיכדלי בסגנון הביטלס והביץ׳ בויז, רוק כבד, מוזיקה אלקטרונית, קאנטרי, פאנק ובלדות תזמורתיות, עם כלי מיתר, כלי נשיפה, סינתיסייזרים והרמוניות קוליות יפות. המילים מצחיקות, מוזרות ופוליטיות, עם הומור וולשי ייחודי. Juxtapozed with U הוא שיר סול רך ומתוק, שבו הזמר גרף ריס שר בקול מעובד, על הצורך להשלים עם אנשים שונים ממך. (Drawing) Rings Around the World, השיר שנתן לאלבום את שמו, הוא שיר רוק מהיר ורועש על העולם המחובר בטלפונים סלולריים. Receptacle for the Respectable הוא שיר שמתחיל כפופ מתוק, עם הלעיסה של מקרטני, ונגמר בפיצוץ של מטאל.''',
'''Rings Around the World נחשב לאחד האלבומים הטובים של הלהקה, ולאחד המגוונים שיצאו מבריטניה באותן שנים. הוא נשמע כמו טיול מסביב לעולם בתוך מוח של מוזיקאי משוגע ומבריק.''',
'''שמעו את Receptacle for the Respectable, ונסו לשמוע את הלעיסה של מקרטני. והשוו ל־Fuzzy Logic (אלבום 808), כדי לשמוע כמה הלהקה גדלה.''',
], [
('Juxtapozed with U', 'שיר סול רך ומתוק, על הצורך להשלים עם אנשים שונים ממך.'),
('(Drawing) Rings Around the World', 'רוק מהיר ורועש על עולם מחובר בטלפונים.'),
('Receptacle for the Respectable', 'מתחיל כפופ מתוק עם לעיסה של מקרטני, ונגמר במטאל.'),
])

add(943, [
'''ג׳וראסיק 5 היא קבוצת היפ הופ מלוס אנג׳לס, שהתגבשה באמצע שנות התשעים מכמה קבוצות קטנות: ארבעה ראפרים, ביניהם צ׳אלי טונה בעל הקול העמוק במיוחד, ושני תקליטנים מבריקים, קאט כמיסט ונו־מארק. בתקופה שבה ההיפ הופ האמריקאי היה מלא בגנגסטרים, כסף וכוח, הם חזרו לרוח של ההיפ הופ של שנות השמונים: מסיבות, הומור, חוכמה ושמחה. Power in Numbers, האלבום השני שלהם, יצא בסוף 2002, והשם שלו, "כוח במספרים", מתאר בדיוק את הרעיון: קבוצה שעובדת יחד.''',
'''הצליל חם, מקפיץ ושמח: דגימות של פאנק, סול וג׳אז ישנים, שריטות מבריקות של שני התקליטנים, וראפרים שמחליפים זה את זה בשורה אחרי שורה, ולפעמים מדברים יחד כמו מקהלה, כמו קבוצות הראפ של פעם. המילים חיוביות, חכמות ומצחיקות, על מוזיקה, על החיים ועל אחריות. What's Golden הוא שיר מקפיץ וקליט, עם קצב פאנקי ופזמון שכולם שרים יחד. Thin Line, עם הזמרת נלי פורטדו, הוא שיר רך ומלודי על הקו הדק בין חברות לאהבה. A Day at the Races הוא שיר מהיר ותחרותי, עם ראפרים אורחים ותיקים, שמזכיר את ימי הזוהר של ההיפ הופ.''',
'''Power in Numbers הוא אחד האלבומים שהחזירו את הכיף להיפ הופ בתחילת שנות האלפיים, והראו שאפשר להיות חכמים וחיוביים בלי להיות משעממים. השפיעו עליהם קבוצות כמו דה לה סול (אלבום 659) ו־A Tribe Called Quest (אלבום 696).''',
'''שמעו את What's Golden, ושימו לב איך הראפרים מעבירים את המיקרופון זה לזה. והשוו ל־The Low End Theory של A Tribe Called Quest (אלבום 696).''',
], [
("What's Golden", 'שיר מקפיץ וקליט, עם קצב פאנקי ופזמון שכולם שרים.'),
('Thin Line', 'שיר רך ומלודי עם נלי פורטדו, על הקו בין חברות לאהבה.'),
('A Day at the Races', 'שיר מהיר ותחרותי, עם ראפרים אורחים ותיקים.'),
])

add(944, [
'''ב־2001 ווילקו, הלהקה של ג׳ף טווידי מ־Being There (אלבום 819), סיימו להקליט אלבום חדש, ניסיוני יותר מכל מה שעשו קודם. חברת התקליטים שלהם שמעה אותו, החליטה שאין לו סיכוי מסחרי, וזרקה את הלהקה. ווילקו לא ויתרו: הם העלו את כל האלבום לאתר שלהם, לשמיעה בחינם, ואלפי מעריצים התלהבו. ואז קרה דבר משעשע: חברת תקליטים אחרת, ששייכת לאותה חברה גדולה, קנתה את האלבום, כך שהחברה שילמה עליו פעמיים. Yankee Hotel Foxtrot יצא באביב 2002, והפך להצלחה הגדולה ביותר של הלהקה.''',
'''הבסיס הוא שירים יפים, מלודיים ועצובים של טווידי, עם גיטרה ופסנתר, אבל מסביבם יש רעשים, צלילים אלקטרוניים, קולות של רדיו, צלצולים ותופים מוזרים, שגורמים לשירים להישמע כמו שידורים שנקלטים מרחוק. השם לקוח מהקלטה של תחנת רדיו שמשדרת מספרים בקוד. I Am Trying to Break Your Heart, שפותח את האלבום, מתחיל ברעשים ובקצב מבולבל, ונבנה לשיר יפה ומוזר. Jesus, Etc. הוא שיר רך ומתוק, עם כינור, ובו שורה על בניינים גבוהים שרועדים, שקיבלה משמעות חדשה אחרי פיגועי 11 בספטמבר, למרות שנכתבה לפניהם. Heavy Metal Drummer הוא שיר שמח ונוסטלגי, על הימים שבהם הלך להופעות של להקות מטאל בקיץ.''',
'''Yankee Hotel Foxtrot נבחר שוב ושוב לאחד האלבומים החשובים של שנות האלפיים, וסיפור ההוצאה שלו הפך לסמל של עצמאות מול תעשיית התקליטים. סרט תיעודי צילם את ההקלטות ואת המאבק.''',
'''שמעו את Jesus, Etc., ואחר כך את I Am Trying to Break Your Heart, ושימו לב לרעשים שמסביב לשירים. והשוו ל־Being There (אלבום 819), כדי לשמוע את הקפיצה.''',
], [
('I Am Trying to Break Your Heart', 'מתחיל ברעשים ובקצב מבולבל, ונבנה לשיר יפה ומוזר.'),
('Jesus, Etc.', 'שיר רך ומתוק עם כינור, ושורה על בניינים גבוהים שרועדים.'),
('Heavy Metal Drummer', 'שיר שמח ונוסטלגי על הופעות מטאל בקיץ.'),
])

add(945, [
'''מיז דיינמייט, ניומי מקלין־דיילי, גדלה בצפון לונדון, למשפחה עם שורשים בג׳מייקה ובסקוטלנד, והתחילה את דרכה כ־MC בסצנת היו־קיי גראז׳, הסגנון של MJ קול (אלבום 906). ב־2001 היא הופיעה בשיר מצליח, וזמן קצר אחר כך הוציאה את אלבום הבכורה שלה, A Little Deeper, באמצע 2002. האלבום זכה בפרס מרקורי, והיא הייתה האישה השחורה הראשונה שזכתה בו. את כספי הפרס היא תרמה לצדקה.''',
'''המוזיקה מחברת רית׳ם אנד בלוז, היפ הופ, רגאיי וגראז׳, עם קצבים חמים, גיטרות, כלי מיתר וקולה החזק והחם של מיז דיינמייט, שעוברת בין שירה לראפ. מה שמייחד את האלבום הוא המילים: שירים אמיצים ואכפתיים על אלימות, על חומרנות, על גזענות ועל משפחה, לצד שירי אהבה ומסיבות. Dy-Na-Mi-Tee, הלהיט הגדול, הוא שיר שמח ומקפיץ עם גיטרה לטינית, הצגה עצמית מלאת ביטחון. It Takes More הוא שיר חכם וכועס נגד ההתמקדות בכסף, בבגדים ובמכוניות במוזיקה ובחברה. Put Him Out הוא שיר כואב על אישה שבן זוגה פוגע בה, וקריאה לה לעזוב.''',
'''A Little Deeper היה אחד האלבומים החשובים של המוזיקה השחורה הבריטית בתחילת שנות האלפיים, והראה שאפשר לעשות פופ מצליח עם מסר רציני. היא המשיכה גם כזמרת אורחת במוזיקה אלקטרונית וכקול מוביל בסצנה הלונדונית. השירים שלה עסקו בנושאים שמעט כוכבות פופ העזו לגעת בהם, וזה בדיוק מה שהפך אותה לקול כל כך חשוב.''',
'''שמעו את It Takes More, והקשיבו למילים. והשוו את מיז דיינמייט ללורין היל ב־The Miseducation of Lauryn Hill (אלבום 869), שתי זמרות־ראפריות עם מסר.''',
], [
('Dy-Na-Mi-Tee', 'שיר שמח ומקפיץ עם גיטרה לטינית, הצגה עצמית מלאת ביטחון.'),
('It Takes More', 'שיר חכם וכועס נגד ההתמקדות בכסף ובחומרנות.'),
('Put Him Out', 'שיר כואב על אישה שבן זוגה פוגע בה, וקריאה לעזוב.'),
])

add(947, [
'''נורה ג׳ונס היא בתו של ראבי שנקר, נגן הסיטאר ההודי המפורסם (אלבום 111), אבל היא גדלה עם אמה בטקסס, והכירה את אביה רק כנערה. היא למדה פסנתר ג׳אז, עברה לניו יורק, ושרה במועדונים קטנים בגריניץ׳ וילג׳. חברת התקליטים המיתולוגית של הג׳אז, בלו נוט, החתימה אותה, ו־Come Away With Me, אלבום הבכורה שלה, יצא בתחילת 2002. הוא הפך לאחת ההצלחות המפתיעות בתולדות המוזיקה: עשרות מיליוני עותקים, ושמונה פרסי גראמי בטקס אחד, ביניהם אלבום השנה.''',
'''המוזיקה רכה, שקטה וחמה, כמו ערב בבית קפה קטן: פסנתר, גיטרה אקוסטית, בס, תופים עדינים, ומעט גיטרת סטיל, בשילוב של ג׳אז, פולק, קאנטרי וסול. הקול של ג׳ונס נמוך, רך, מעט צרוד ומלטף, והיא שרה בלי מאמץ, כמעט בלחישה. Don't Know Why, הלהיט הגדול, הוא שיר אהבה נוגה ועדין, עם פסנתר רך, על מי שלא הגיע לפגישה, והוא זכה בגראמי לשיר ולהקלטה של השנה. Come Away With Me, השיר שנתן לאלבום את שמו, שכתבה בעצמה, הוא הזמנה רכה ושקטה לברוח יחד. Cold Cold Heart הוא גרסה ג׳אזית ואיטית לשיר הקאנטרי הקלאסי של האנק וויליאמס.''',
'''Come Away With Me הפך את נורה ג׳ונס לכוכבת עולמית, והראה שמוזיקה שקטה ועדינה יכולה לנצח את המצעדים באמצע עידן של פופ רועש. רבים קנו אותו כאלבום לערב רגוע או לארוחת ערב, והוא נשאר אחד האלבומים הנמכרים של שנות האלפיים.''',
'''זה אלבום לערב שקט, עם כוס תה או יין. שמעו את Cold Cold Heart, והשוו לגרסה המקורית של האנק וויליאמס. ואם אהבתם את Blue של ג׳וני מיטשל (אלבום 229), תרגישו כאן בבית.''',
], [
("Don't Know Why", 'שיר אהבה נוגה ועדין עם פסנתר רך, זכה בגראמי.'),
('Come Away With Me', 'הזמנה רכה ושקטה לברוח יחד, שכתבה בעצמה.'),
('Cold Cold Heart', 'גרסה ג׳אזית ואיטית לשיר הקאנטרי הקלאסי של האנק וויליאמס.'),
])

add(948, [
'''שנתיים אחרי Parachutes (אלבום 916), קולדפליי הוציאו את A Rush of Blood to the Head, בקיץ 2002, והפכו בבת אחת מלהקה צעירה ומבטיחה לאחת הלהקות הגדולות בעולם. הלחץ היה עצום, והלהקה זרקה הרבה שירים בדרך, עד שהרגישה שיש לה אלבום טוב יותר מהראשון. האלבום הגיע למקום הראשון במצעד הבריטי, נמכר במיליוני עותקים, וזכה בגראמי לאלבום האלטרנטיבי הטוב ביותר.''',
'''הצליל רחב, בטוח ודרמטי יותר מבאלבום הראשון: פסנתר גדול, גיטרות מהדהדות, תופים חזקים, ולפעמים צלילים אלקטרוניים, עם הקול של כריס מרטין שעובר בין לחישה לשירה מלאה. השירים עוסקים באהבה, בחרטה, בפחד ובתקווה. Clocks, אחד השירים המפורסמים של הלהקה, בנוי סביב ריף פסנתר מהיר וחוזר, שאי אפשר לשכוח, והוא זכה בגראמי להקלטה של השנה. The Scientist הוא בלדת פסנתר עצובה ויפה, על הרצון לחזור להתחלה ולתקן טעות באהבה, והקליפ שלו, שצולם מהסוף להתחלה, הפך למפורסם. In My Place, שיר הסינגל הראשון, הוא שיר גיטרה מרגש ופשוט, על המתנה למישהו שאוהבים.''',
'''A Rush of Blood to the Head נחשב בעיני רבים לאלבום הטוב ביותר של קולדפליי, ולאחד האלבומים החשובים של הרוק הבריטי בתחילת שנות האלפיים. אחריו הלהקה הפכה לאחת להקות האצטדיונים הגדולות בעולם. רבים זוכרים את התקופה הזאת כרגע שבו קולדפליי הפכו מבטחה צעירה לאחת הלהקות שמגדירות דור.''',
'''שמעו את Clocks, ושימו לב לריף הפסנתר שחוזר לאורך כל השיר. והשוו את The Scientist ל־Trouble מ־Parachutes (אלבום 916), כדי לשמוע איך מרטין התפתח.''',
], [
('Clocks', 'ריף פסנתר מהיר וחוזר שאי אפשר לשכוח, זכה בגראמי.'),
('The Scientist', 'בלדת פסנתר עצובה ויפה, על הרצון לחזור להתחלה.'),
('In My Place', 'שיר גיטרה מרגש ופשוט, על המתנה למישהו שאוהבים.'),
])

add(949, [
'''דה קורל הם שישה צעירים מהוילייק, עיירת חוף קטנה ליד ליברפול, שהתחילו לנגן יחד כשהיו עוד בבית הספר. הם אהבו מוזיקה ישנה מכל הסוגים: שירי ים של מלחים, רוק פסיכדלי של שנות השישים, להקות מליברפול, ג׳אז ישן, ואת המוזיקה המוזרה של קפטן ביפהארט (אלבומים 83 ו־136). The Coral, אלבום הבכורה שלהם, יצא בקיץ 2002, הגיע לעשירייה הראשונה במצעד הבריטי, והיה מועמד לפרס מרקורי. את האלבום הפיק איאן ברודי, מוזיקאי ותיק מליברפול.''',
'''המוזיקה קופצת מסגנון לסגנון, לפעמים בתוך אותו שיר: פופ של שנות השישים, שירי ים, סקא, רוק פסיכדלי, קאנטרי ומוזיקה של סרטי מערבונים, עם גיטרות, אורגן, מפוחית, כלי נשיפה והרמוניות קוליות. הזמר ג׳יימס סקלי שר בקול עמוק, מחוספס ובוגר הרבה יותר מגילו. Dreaming of You, הלהיט הגדול, הוא שיר אהבה קצר, שמח ומקפיץ, עם אורגן ופזמון מתוק. Goodbye הוא שיר פסיכדלי ודרמטי, שמתחיל בשקט ונבנה לפיצוץ אדיר של גיטרות. Simon Diamond הוא שיר מוזר ומצחיק, שנשמע כמו שיר ילדים אפל, על דמות מסתורית.''',
'''The Coral נחשב לאחד מאלבומי הבכורה המקוריים של הרוק הבריטי בתחילת שנות האלפיים, והמשיך את המסורת הארוכה של להקות מליברפול שאוהבות מלודיות גדולות, מהביטלס ועד שאק (אלבום 898). הלהקה המשיכה להוציא אלבומים רבים, ונשארה אהובה מאוד בבריטניה.''',
'''שמעו את Dreaming of You, ושימו לב לאורגן. ואם אהבתם את Forever Changes של לאב (אלבום 87), תמצאו כאן את אותה רוח פסיכדלית ומלודית.''',
], [
('Dreaming of You', 'שיר אהבה קצר, שמח ומקפיץ, עם אורגן ופזמון מתוק.'),
('Goodbye', 'שיר פסיכדלי ודרמטי, שנבנה מהשקט לפיצוץ אדיר.'),
('Simon Diamond', 'שיר מוזר ומצחיק, כמו שיר ילדים אפל על דמות מסתורית.'),
])

add(950, [
'''ג׳וני קאש, אחד מגדולי זמרי הקאנטרי ואחת הדמויות החשובות במוזיקה האמריקאית, היה בשנות השמונים כמעט נשכח, בלי חברת תקליטים. ב־1994 פנה אליו המפיק ריק רובין, שעבד עם להקות היפ הופ ומטאל, והציע לו להקליט אלבומים פשוטים, רק הוא וגיטרה, עם שירים ישנים וחדשים. כך נולדה סדרת אלבומי American, שהחזירה את קאש לחיים. American IV: The Man Comes Around, שיצא בסוף 2002, היה האחרון שיצא בחייו. הוא כבר היה חולה מאוד, והקול שלו שבור, עייף ועמוק.''',
'''רוב השירים הם גרסאות לשירים של אחרים, מכל הסגנונות: קאנטרי, פולק, פופ, רוק ואפילו להקות אלקטרוניות, וכל אחד מהם נשמע אצל קאש כמו תפילה או פרידה. Hurt, השיר המפורסם, הוא גרסה לשיר של ניין אינץ׳ ניילס (אלבום 782), על כאב וחרטה, ובקולו של קאש הזקן הוא נשמע כמו סיכום של חיים שלמים. הקליפ שלו, שבו קאש יושב במוזיאון סגור שהוקדש לו, עם תמונות מצעירותו, נחשב לאחד הקליפים המרגשים שצולמו. The Man Comes Around, השיר שכתב בעצמו, הוא שיר אפל ומרשים על יום הדין. Personal Jesus הוא גרסה בלוזית, עם גיטרה אקוסטית, לשיר של להקת הסינת׳ פופ דפש מוד.''',
'''כמה חודשים אחרי צאת האלבום מתה אשתו ואהבת חייו, ג׳ון קרטר קאש, ובספטמבר 2003 מת גם הוא. American IV נחשב לאחת הפרידות היפות והמרגשות בתולדות המוזיקה. באלבום שרים איתו גם אורחים, ביניהם פיונה אפל (אלבום 818).''',
'''שמעו את Hurt, ואחר כך את הגרסה המקורית של ניין אינץ׳ ניילס ב־The Downward Spiral (אלבום 782). והשוו את קאש הזקן לקאש הצעיר ב־At Folsom Prison (אלבום 115).''',
], [
('Hurt', 'גרסה לשיר של ניין אינץ׳ ניילס, כמו סיכום של חיים שלמים.'),
('The Man Comes Around', 'שיר אפל ומרשים על יום הדין, שכתב בעצמו.'),
('Personal Jesus', 'גרסה בלוזית ואקוסטית לשיר של דפש מוד.'),
])

add(918, [
'''מייק לאד הוא משורר, ראפר ומוזיקאי אמריקאי, שגדל בבוסטון ופעל בניו יורק, בסצנה שבה שירה, היפ הופ ומוזיקה ניסיונית נפגשו. הוא הופיע בערבי שירה, כתב טקסטים ארוכים ומלאי דימויים, ובניגוד לרוב הראפרים של אותה תקופה, התעניין במדע בדיוני, בפוליטיקה ובעתיד. Welcome to the Afterfuture, שיצא ב־2000, הוא אלבום שמתאר עתיד אפל, טכנולוגי ומשונה, מנקודת מבט של אמריקאי שחור, ברוח שנקראת "אפרו־פיוצ׳ריזם": דמיון של עתיד שבו שחורים הם הגיבורים, לא הקורבנות.''',
'''המוזיקה רועשת, צפופה וניסיונית: קצבים כבדים ושבורים של היפ הופ, צלילים אלקטרוניים מעוותים, רעשים, דגימות ולפעמים גיטרות של פאנק, והכל נשמע כמו שידור רדיו מעתיד מבולבל. לאד עושה ראפ ומדקלם שירה בקול חד ומהיר, עם מילים מלאות בהומור, כעס, מדע ופוליטיקה. 5000 Miles West of the Future, שפותח את האלבום, הוא פתיחה דרמטית שמכניסה את המאזין לעולם העתידני. Airwave Hysteria הוא שיר מהיר ועצבני על הצפת התקשורת והרדיו. Takes More Than 41 הוא שיר כועס ועצוב, שנכתב בעקבות מקרה שבו נורה צעיר אפריקאי לא חמוש בניו יורק בידי שוטרים, ב־1999, ונגע בעצב חשוף בעיר.''',
'''Welcome to the Afterfuture הוא אלבום שהיה תמיד מחוץ לזרם המרכזי, אבל השפיע על אמנים שחיברו היפ הופ, שירה ומוזיקה ניסיונית. בהמשך עבד לאד עם הפסנתרן ג׳אז ויג׳אי אייר, ויצר עבודות שמשלבות מוזיקה, שירה ותיאטרון.''',
'''זה אלבום תובעני, שכדאי לשמוע באוזניות ולהקשיב למילים. ואם אהבתם את Dr. Octagonecologyst (אלבום 810), תמצאו כאן עוד צד מוזר ועתידני של ההיפ הופ.''',
], [
('5000 Miles West of the Future', 'פתיחה דרמטית שמכניסה את המאזין לעולם עתידני ומשונה.'),
('Airwave Hysteria', 'שיר מהיר ועצבני על הצפת התקשורת והרדיו.'),
('Takes More Than 41', 'שיר כועס ועצוב, בעקבות מקרה ירי משטרתי בניו יורק.'),
])

add(919, [
'''רד סנאפר הם שלושה מוזיקאים מלונדון: המתופף ריצ׳רד ת׳יר, הקונטרבסיסט עלי פרנד והגיטריסט דייוויד איירס. בתקופה שבה מוזיקה אלקטרונית נעשתה בעיקר במחשבים ובמכונות, הם ניגנו אותה בנגינה חיה, עם תופים, קונטרבס וגיטרה אמיתיים: טריפ הופ, דראם אנד בייס, ג׳אז ודאב, כמו להקת ג׳אז שמנגנת במועדון לילה. הם חתמו בחברת התקליטים הבריטית וורפ, ו־Our Aim Is to Satisfy, שיצא ב־2000, היה האלבום השלישי שלהם, ובמשך כמה שנים האחרון.''',
'''הצליל חם, מתוח ומקפיץ: תופים מהירים ושבורים שמנוגנים ביד, קונטרבס עמוק כמו בג׳אז, גיטרה מהדהדת, כלי נשיפה, וצלילים אלקטרוניים עדינים. בכמה מהשירים מצטרפים זמרים וראפרים, ביניהם MC דט, אחד הקולות המוכרים של סצנת הג׳אנגל הלונדונית. The Rough and the Quick, עם הזמרת קרמי קנדרה, הוא שיר רך ומפתה, עם קצב שבור ובס עמוק. Keeping Pigs Together, שפותח את האלבום, הוא קטע כלי מתוח ומקפיץ, עם קונטרבס וגיטרה שמשוחחים זה עם זה. Some Kind of Kink, עם MC דט, הוא קטע מהיר ואנרגטי, עם ראפ חד מעל תופים חיים.''',
'''רד סנאפר אף פעם לא היו מפורסמים מאוד, אבל הם היו מוערכים במיוחד בקרב מוזיקאים, והראו שאפשר לנגן מוזיקה אלקטרונית בידיים. אחרי האלבום הזה הלהקה נפרדה, וחזרה כמה שנים מאוחר יותר.''',
'''שמעו את Keeping Pigs Together, ושימו לב שכל התופים והבס מנוגנים ביד, לא במכונה. והשוו ל־New Forms של רוני סייז (אלבום 855), שגם הוא שילב קונטרבס חי.''',
], [
('The Rough and the Quick', 'שיר רך ומפתה, עם קצב שבור ובס עמוק.'),
('Keeping Pigs Together', 'קטע כלי מתוח ומקפיץ, קונטרבס וגיטרה שמשוחחים.'),
('Some Kind of Kink', 'קטע מהיר ואנרגטי, ראפ חד מעל תופים חיים.'),
])

add(922, [
'''ג׳יינט סאנד היא הלהקה של האו גלב, מוזיקאי מטוסון שבאריזונה, שמנגן כבר מאמצע שנות השמונים מוזיקה שנשמעת כמו המדבר: רחבה, מאובקת, מוזרה וחמה. הלהקה החליפה חברים פעמים רבות, ושניים מהם, ג׳ואי ברנס וג׳ון קונברטינו, הקימו מאוחר יותר את להקת קלקסיקו. Chore of Enchantment, שיצא ב־2000, נולד בתקופה קשה: גלב איבד חבר קרוב, הגיטריסט ריינר פטצ׳ק, שמת מסרטן, והאלבום מוקדש לו במידה רבה. הוא הוקלט בכמה מקומות, עם כמה מפיקים שונים, ובכל זאת נשמע מאוחד ואישי.''',
'''המוזיקה מחברת קאנטרי, רוק, פולק, ג׳אז ומוזיקה של מדבר, עם גיטרות מחוספסות, פסנתר, מפוחית, תופים פשוטים וצלילים מוזרים, והקול של גלב, עמוק, מדבר ומתגלגל, כמו מספר סיפורים שעונה לעצמו. השירים מתחלפים בין רגעים יפים ושקטים לבין רעש ובלגן משועשע, וזה חלק מהקסם. (Well) Dusted (For the Millenium) הוא שיר מתגלגל ומאובק, עם גיטרה מחוספסת ומילים מצחיקות על סוף העולם. Shiver הוא שיר שקט ויפה, עם פסנתר וקול רך. Temptation of Egg הוא קטע פסנתר עדין ומהורהר, כמעט ג׳אזי, שמזכיר שגלב הוא גם פסנתרן מצוין.''',
'''Chore of Enchantment נחשב לאחד האלבומים הטובים של ג׳יינט סאנד, ולאחד מאבני היסוד של מה שנקרא "דזרט רוק" או "אמריקנה של המדבר". גלב נשאר מוזיקאי פורה ומוערך, שהקליט עשרות אלבומים, לבד ועם אחרים.''',
'''זה אלבום טוב לנסיעה במדבר, או לערב חם עם חלון פתוח. ואם אהבתם את Heartbreaker של ראיין אדמס (אלבום 904), תמצאו כאן צד מוזר ומאובק יותר של האמריקנה.''',
], [
('(Well) Dusted (For the Millenium)', 'שיר מתגלגל ומאובק, עם גיטרה מחוספסת ומילים על סוף העולם.'),
('Shiver', 'שיר שקט ויפה, עם פסנתר וקול רך.'),
('Temptation of Egg', 'קטע פסנתר עדין ומהורהר, כמעט ג׳אזי.'),
])

add(924, [
'''אוטה למפר היא זמרת ושחקנית מגרמניה, שהתפרסמה בשנות השמונים כמפרשת נפלאה של השירים של קורט וייל וברטולט ברכט, הקברט הגרמני של שנות העשרים והשלושים, ושל זמרות כמו מרלן דיטריך. היא גם כיכבה במחזות זמר בלונדון ובברודווי, וזכתה בפרס חשוב על תפקידה ב"שיקגו". Punishing Kiss, שיצא ב־2000, היה רעיון חדש: במקום שירים ישנים, היא ביקשה מכותבי שירים מודרניים להתנהג כמו וייל וברכט, ולכתוב בשבילה שירים חדשים ברוח הקברט.''',
'''הרשימה מרשימה: אלביס קוסטלו, ניק קייב, טום ווייטס, סקוט ווקר, ניל הנון מדה דיוויין קומדי (אלבום 848), והמלחין פיליפ גלאס. דה דיוויין קומדי גם מלווים אותה בחלק מהשירים. המוזיקה תיאטרלית, דרמטית ואלגנטית, עם כלי מיתר, פסנתר, אקורדיון וכלי נשיפה, וקולה של למפר עובר מלחישה מפתה לשירה עוצמתית ואפלה, כמו שחקנית על במה. Little Water Song, של ניק קייב, הוא שיר אפל ומפחיד על אישה שטבעה, שמסופר מנקודת המבט שלה. Punishing Kiss, של אלביס קוסטלו, השיר שנתן לאלבום את שמו, הוא שיר אהבה מר ודרמטי. Scope J, של סקוט ווקר, הוא שיר מוזר, קודר ומאיים, בסגנון הניסיוני שאפיין אותו בשנים המאוחרות.''',
'''Punishing Kiss הוא אחד הניסיונות היפים לחבר בין הקברט הישן לבין כותבי השירים של היום, והוא מראה עד כמה הרוח של וייל וברכט עדיין חיה. למפר המשיכה להופיע בכל העולם, ולשיר בשפות רבות.''',
'''שמעו את Little Water Song, ואחר כך את Murder Ballads של ניק קייב (אלבום 827), שנכתב באותה רוח. והשוו את Scope J ל־Scott 4 של סקוט ווקר (אלבום 170).''',
], [
('Little Water Song', 'שיר אפל ומפחיד של ניק קייב, מנקודת מבטה של אישה שטבעה.'),
('Punishing Kiss', 'שיר אהבה מר ודרמטי, שכתב אלביס קוסטלו.'),
('Scope J.', 'שיר מוזר, קודר ומאיים, שכתב סקוט ווקר.'),
])

add(938, [
'''דה בטא בנד היא להקה סקוטית, שהתפרסמה ב־1998 עם אוסף של שלושה תקליטים קצרים, שנחשב לאחד היפים של התקופה. אחד השירים ממנו הופיע בסרט "נאמנות גבוהה", בסצנה שבה בעל חנות התקליטים מכריז שהוא עומד למכור חמישה עותקים, ומשמיע אותו ללקוחות. אלבום הבכורה של הלהקה, ב־1999, אכזב, והחברים עצמם אמרו לעיתונות שהוא גרוע. Hot Shots II, שיצא ב־2001, היה התיקון: אלבום מגובש, שקט ויפה, שהפיק מפיק היפ הופ ורית׳ם אנד בלוז בריטי.''',
'''המוזיקה מחברת פולק, רוק פסיכדלי, היפ הופ, מוזיקה אלקטרונית ודאב, בצורה רגועה, מנומנמת ומהפנטת. יש כאן קצבים רכים של היפ הופ, גיטרות אקוסטיות, סינתיסייזרים, הרמוניות קוליות וקולו הרך והעייף של סטיב מייסון. השירים נשמעים כמו שיחה שקטה בחדר מעושן בשעה מאוחרת. Squares, שפותח את האלבום, הוא שיר מלנכולי ויפה, שבנוי על דגימה מתקליט ישן, עם קצב איטי ושירה עדינה. Human Being הוא שיר אופטימי ורך, על הקושי והיופי של להיות בן אדם. Broke הוא שיר נינוח ומהפנט, עם קצב רגוע וגיטרה מתגלגלת.''',
'''Hot Shots II נחשב לאלבום הטוב ביותר של הבטא בנד, אבל הלהקה אף פעם לא הצליחה מסחרית כמו שציפו, והתפרקה כמה שנים אחר כך. היא השפיעה על להקות רבות, ובהן רדיוהד וקולדפליי, שדיברו על אהבתם אליה.''',
'''שמעו את Squares בשעת לילה, ותנו לקצב האיטי להוביל אתכם. ואם אהבתם את Endtroducing של די ג׳יי שאדו (אלבום 815), תמצאו כאן צד שירי של אותה רוח.''',
], [
('Squares', 'שיר מלנכולי ויפה, על דגימה ישנה, עם קצב איטי ושירה עדינה.'),
('Human Being', 'שיר אופטימי ורך, על הקושי והיופי של להיות בן אדם.'),
('Broke', 'שיר נינוח ומהפנט, עם קצב רגוע וגיטרה מתגלגלת.'),
])

add(946, [
'''הביז הם שני חברים מהאי וייט, אי קטן בדרום אנגליה: פול באטלר ואהרון פלטשר. הם אספו תקליטים ישנים מכל העולם, של סול, רגאיי, ג׳אז, פסיכדליה וברזיל, והקליטו את אלבום הבכורה שלהם, Sunshine Hit Me, בצריף בחצר של הוריו של באטלר, עם ציוד ישן וזול. האלבום יצא ב־2002 בחברה קטנה, והיה מועמד לפרס מרקורי, הפתעה גדולה ללהקה שכמעט איש לא שמע עליה. באמריקה הם נאלצו להופיע בשם "א בנד אוף ביז", בגלל להקה אחרת עם אותו שם.''',
'''המוזיקה חמה, שמשית ומעט מבולגנת, כמו אחר צהריים של קיץ בשנות השישים: גיטרות רכות, אורגן, כלי נשיפה, תופים חמים, בס עגול וקולות רכים, עם השפעות של סול, רגאיי, פסיכדליה ומוזיקה ברזילאית. הכל נשמע ישן ורענן באותו זמן. A Minha Menina היא גרסה עליזה לשיר של להקת הרוק הברזילאית אוס מוטנטס, ששרים אותה בפורטוגזית, והיא הפכה למוכרת אחרי שהופיעה בפרסומת. Punchbag, שפותח את האלבום, הוא קטע נינוח ושמשי, עם כלי נשיפה וקצב רגוע. Binnel Bay, על שם מפרץ באי וייט, הוא שיר רגאיי רך וחולמני.''',
'''Sunshine Hit Me הוא אחד מאלבומי הבכורה המקסימים של תחילת שנות האלפיים, והראה שאפשר ליצור משהו יפה ומקורי בצריף בחצר. הביז המשיכו להוציא אלבומים, ונשארו אהובים על אוהבי מוזיקה רטרו חמה.''',
'''זה אלבום מושלם לבוקר של שבת בקיץ. שמעו את A Minha Menina, ואם אהבתם את Tanto Tempo של בבל ז׳ילברטו (אלבום 905), תמצאו כאן עוד חיבור יפה לברזיל.''',
], [
('A Minha Menina', 'גרסה עליזה לשיר של אוס מוטנטס, בפורטוגזית.'),
('Punchbag', 'קטע נינוח ושמשי, עם כלי נשיפה וקצב רגוע.'),
('Binnel Bay', 'שיר רגאיי רך וחולמני, על מפרץ באי וייט.'),
])
